export const TECH_STATUSES = ["SOUND", "DAMAGED", "IN_REPAIR", "HOLD"] as const;
export type TechStatus = (typeof TECH_STATUSES)[number];
export const TECH_STATUS_LABELS: Record<TechStatus, string> = {
