export const PAYMENT_STATUSES = ["PAID", "PENDING", "OVERDUE"] as const;
export type PaymentStatus = (typeof PAYMENT_STATUSES)[number];
export const PAYMENT_STATUS_LABELS: Record<PaymentStatus, string> = {
