/** UN/LOCODE, с которыми работает компания. */
export const LOCATIONS = [
  { code: "RUVVO", city: "Владивосток", region: "Владивосток", terminals: ["ВМТП", "ПКТ", "Терминал Моряк-Рыболов"] },
