  { code: "RUMOW", city: "Москва", region: "Москва", terminals: ["ТЛЦ Ворсино", "ТЛЦ Ховрино", "ТЛЦ Белый Раст", "ТЛЦ Электроугли"] },
  { code: "RUNVR", city: "Новороссийск", region: "Новороссийск", terminals: ["НУТЭП", "НЛЭ", "Новороссийский МТП"] },
  { code: "RUOVB", city: "Новосибирск", region: "Сибирь и Урал", terminals: ["ТК Клещиха", "ТЛЦ Чемской"] },
  { code: "RUYEK", city: "Екатеринбург", region: "Сибирь и Урал", terminals: ["ТЛЦ Екатеринбург-Товарный", "ТК Шарташ"] },
  { code: "CNSHA", city: "Шанхай", region: "Китай", terminals: ["Shanghai SIPG", "Yangshan Phase IV"] },
  { code: "CNNGB", city: "Нинбо", region: "Китай", terminals: ["Ningbo Beilun", "Ningbo Meishan"] },
  { code: "CNTSN", city: "Тяньцзинь", region: "Китай", terminals: ["Tianjin TCT"] },
  { code: "TRIST", city: "Стамбул", region: "Турция", terminals: ["Ambarli Marport", "Kumport"] },
] as const;

export const REGIONS = ["Владивосток", "Санкт-Петербург", "Москва", "Новороссийск", "Сибирь и Урал", "Китай", "Турция"] as const;

const LOCATION_BY_CODE = new Map<string, (typeof LOCATIONS)[number]>(LOCATIONS.map((l) => [l.code, l]));

export function locodeCity(code: string): string {
  return LOCATION_BY_CODE.get(code)?.city ?? code;
}

export function locodeRegion(code: string): string {
  return LOCATION_BY_CODE.get(code)?.region ?? "Прочие";
}

export function terminalsOf(code: string): readonly string[] {
  return LOCATION_BY_CODE.get(code)?.terminals ?? [];
}

/** Пороги контроля. */
export const THRESHOLDS = {
  cscWarningDays: 30,
  oneWayHotDays: 5,
  idleStockDays: 30,
  leaseExpiringCriticalDays: 14,
  leaseExpiringWarningDays: 30,
} as const;

export function isOneOf<T extends string>(list: readonly T[], value: string): value is T {
  return (list as readonly string[]).includes(value);
}
import { addDays, diffDays } from "@/lib/dates";
import { THRESHOLDS, type StoredTripStatus, type TripStatus } from "./constants";

export interface TripTimingInput {
  status: string;
  handoverDate: Date;
  freeDays: number;
  deadlineDate: Date;
  actualReturnDate: Date | null;
  detentionRatePerDayUsd: number;
}

export interface TripTiming {
  /** Эффективный статус: ACTIVE с прошедшим дедлайном становится OVERDUE. */
  status: TripStatus;
  /** Сколько свободных дней осталось (только для ACTIVE). */
  daysLeft: number | null;
  /** Дней просрочки на сегодня или на дату фактического возврата. */
  overdueDays: number;
  /** Начисленный детеншн, USD. */
  detentionUsd: number;
  /** Дедлайн ≤ 5 дней и ещё не наступил. */
  isHot: boolean;
  /** Доля использованных свободных дней 0..1 (для прогресс-бара). */
  freeDaysUsedRatio: number;
}

export function computeDeadline(handoverDate: Date, freeDays: number): Date {
  return addDays(handoverDate, freeDays);
}

export function computeTripTiming(trip: TripTimingInput, now: Date): TripTiming {
  const stored = trip.status as StoredTripStatus;
  const isClosed = stored === "COMPLETED" || stored === "DISPUTE";
  const referenceDate = isClosed && trip.actualReturnDate ? trip.actualReturnDate : now;

  const daysToDeadline = diffDays(referenceDate, trip.deadlineDate);
  const overdueDays = Math.max(0, -daysToDeadline);
  const detentionUsd = overdueDays * trip.detentionRatePerDayUsd;
  const usedDays = diffDays(trip.handoverDate, referenceDate);
  const freeDaysUsedRatio = trip.freeDays > 0 ? Math.min(1, Math.max(0, usedDays / trip.freeDays)) : 1;

  if (isClosed) {
    return { status: stored, daysLeft: null, overdueDays, detentionUsd, isHot: false, freeDaysUsedRatio };
  }

  const isOverdue = overdueDays > 0;
  return {
    status: isOverdue ? "OVERDUE" : "ACTIVE",
    daysLeft: isOverdue ? null : daysToDeadline,
    overdueDays,
    detentionUsd,
    isHot: !isOverdue && daysToDeadline <= THRESHOLDS.oneWayHotDays,
    freeDaysUsedRatio,
  };
}
import { addDays, daysInMonthUtc, diffDays, startOfMonthUtc } from "@/lib/dates";
import { THRESHOLDS } from "./constants";

export interface LeaseItemInput {
  onHireDate: Date;
  offHireDate: Date | null;
}

export interface LeaseInput {
  status: string;
  endDate: Date;
  dailyRateUsd: number;
  paymentStatus: string;
  items: readonly LeaseItemInput[];
}

export type LeaseExpiryLevel = "EXPIRED" | "CRITICAL" | "WARNING" | "OK" | "CLOSED";

export interface LeaseMetrics {
  activeUnits: number;
  totalUnits: number;
  daysToEnd: number;
  expiryLevel: LeaseExpiryLevel;
  /** Начислено за текущий календарный месяц по сегодняшний день включительно. */
  accruedThisMonthUsd: number;
  /** Начислено за весь срок договора. */
  accruedTotalUsd: number;
  /** Плановый доход в месяц при текущем числе единиц на руках. */
  monthlyRunRateUsd: number;
  needsAttention: boolean;
}

/** Дни аренды единицы в интервале [from, to] включительно, с учётом On-Hire/Off-Hire. */
export function rentalDaysInRange(item: LeaseItemInput, from: Date, to: Date): number {
  const start = item.onHireDate > from ? item.onHireDate : from;
  // День Off-Hire не тарифицируется, поэтому последний оплачиваемый день — накануне.
  const lastBillable = item.offHireDate ? addDays(item.offHireDate, -1) : to;
  const end = lastBillable < to ? lastBillable : to;
  const days = diffDays(start, end) + 1;
  return Math.max(0, days);
}

export function expiryLevelOf(daysToEnd: number, isClosed: boolean): LeaseExpiryLevel {
  if (isClosed) return "CLOSED";
  if (daysToEnd < 0) return "EXPIRED";
  if (daysToEnd <= THRESHOLDS.leaseExpiringCriticalDays) return "CRITICAL";
  if (daysToEnd <= THRESHOLDS.leaseExpiringWarningDays) return "WARNING";
  return "OK";
}

export function computeLeaseMetrics(lease: LeaseInput, now: Date): LeaseMetrics {
  const isClosed = lease.status === "COMPLETED";
  const activeUnits = lease.items.filter((i) => !i.offHireDate).length;
  const daysToEnd = diffDays(now, lease.endDate);
  const monthStart = startOfMonthUtc(now);
  const farPast = new Date(0);

  const accruedThisMonthUsd = lease.items.reduce(
    (sum, item) => sum + rentalDaysInRange(item, monthStart, now) * lease.dailyRateUsd,
    0,
  );
  const accruedTotalUsd = lease.items.reduce(
    (sum, item) => sum + rentalDaysInRange(item, farPast, now) * lease.dailyRateUsd,
    0,
  );
  const expiryLevel = expiryLevelOf(daysToEnd, isClosed);

  return {
    activeUnits,
    totalUnits: lease.items.length,
    daysToEnd,
    expiryLevel,
    accruedThisMonthUsd,
    accruedTotalUsd,
    monthlyRunRateUsd: activeUnits * lease.dailyRateUsd * daysInMonthUtc(now),
    needsAttention:
      !isClosed && (lease.paymentStatus === "OVERDUE" || expiryLevel === "CRITICAL" || expiryLevel === "WARNING" || expiryLevel === "EXPIRED"),
  };
}

export function parseLocodeList(csv: string): string[] {
  return csv
    .split(",")
    .map((s) => s.trim().toUpperCase())
    .filter(Boolean);
}
import { attentionFlagsOf, type AttentionInput } from "./container";
import { computeLeaseMetrics, type LeaseInput } from "./lease";
import { computeTripTiming, type TripTimingInput } from "./one-way";
import {
  OPERATIONAL_STATUSES,
  REGIONS,
  UTILIZED_STATUSES,
  isOneOf,
  locodeRegion,
  teuOf,
  type OperationalStatus,
} from "./constants";

export interface FleetContainerInput extends AttentionInput {
  sizeType: string;
  currentLocode: string;
}

export interface FleetKpi {
  totalUnits: number;
  totalTeu: number;
  utilizationRate: number;
  utilizedUnits: number;
  oneWay: { active: number; hot: number; overdue: number; detentionUsd: number };
  lease: { activeContracts: number; unitsOnHire: number; monthlyRevenueUsd: number; attention: number };
  attention: { total: number; csc: number; repair: number; idle: number };
  byRegion: { region: string; units: number; teu: number }[];
  byStatus: { status: OperationalStatus; units: number }[];
}

export function computeFleetKpi(
  containers: readonly FleetContainerInput[],
  trips: readonly TripTimingInput[],
  leases: readonly LeaseInput[],
  now: Date,
): FleetKpi {
  const totalUnits = containers.length;
  const totalTeu = containers.reduce((sum, c) => sum + teuOf(c.sizeType), 0);
  const utilizedUnits = containers.filter(
    (c) => isOneOf(OPERATIONAL_STATUSES, c.operationalStatus) && UTILIZED_STATUSES.includes(c.operationalStatus),
  ).length;

  const tripTimings = trips.map((t) => computeTripTiming(t, now));
  const openTrips = tripTimings.filter((t) => t.status === "ACTIVE" || t.status === "OVERDUE");

  const leaseMetrics = leases.filter((l) => l.status === "ACTIVE").map((l) => computeLeaseMetrics(l, now));

  const flags = containers.map((c) => attentionFlagsOf(c, now));

  const regionOrder: string[] = [...REGIONS, "Прочие"];
  const byRegion = regionOrder
    .map((region) => {
      const inRegion = containers.filter((c) => locodeRegion(c.currentLocode) === region);
      return { region, units: inRegion.length, teu: inRegion.reduce((s, c) => s + teuOf(c.sizeType), 0) };
    })
    .filter((r) => r.units > 0);

  const byStatus = OPERATIONAL_STATUSES.map((status) => ({
    status,
    units: containers.filter((c) => c.operationalStatus === status).length,
  }));

  return {
    totalUnits,
    totalTeu,
    utilizedUnits,
    utilizationRate: totalUnits > 0 ? utilizedUnits / totalUnits : 0,
    oneWay: {
      active: openTrips.length,
      hot: openTrips.filter((t) => t.isHot).length,
      overdue: openTrips.filter((t) => t.status === "OVERDUE").length,
      detentionUsd: openTrips.reduce((s, t) => s + t.detentionUsd, 0),
    },
    lease: {
      activeContracts: leaseMetrics.length,
      unitsOnHire: leaseMetrics.reduce((s, m) => s + m.activeUnits, 0),
      monthlyRevenueUsd: leaseMetrics.reduce((s, m) => s + m.monthlyRunRateUsd, 0),
      attention: leaseMetrics.filter((m) => m.needsAttention).length,
    },
    attention: {
      total: flags.filter((f) => f.any).length,
      csc: flags.filter((f) => f.csc.level !== "OK").length,
      repair: flags.filter((f) => f.needsRepair).length,
      idle: flags.filter((f) => f.storage.isIdleTooLong).length,
    },
    byRegion,
    byStatus,
  };
}
import { diffDays } from "@/lib/dates";
import { TECH_STATUS_LABELS, TECH_STATUSES, THRESHOLDS, isOneOf } from "./constants";

export type CscLevel = "EXPIRED" | "EXPIRING" | "OK";

export interface CscState {
  level: CscLevel;
  daysLeft: number;
}

export function cscStateOf(cscPlateExpiry: Date, now: Date): CscState {
  const daysLeft = diffDays(now, cscPlateExpiry);
  if (daysLeft < 0) return { level: "EXPIRED", daysLeft };
  if (daysLeft <= THRESHOLDS.cscWarningDays) return { level: "EXPIRING", daysLeft };
  return { level: "OK", daysLeft };
}

export interface IssueCandidateInput {
  operationalStatus: string;
  techStatus: string;
  cscPlateExpiry: Date;
}

/**
 * Почему контейнер нельзя выдать (One-Way, аренда, собственный рейс). null — выдача разрешена.
 * Единая точка истины для форм и серверных проверок.
 */
export function issueBlockReason(c: IssueCandidateInput, now: Date): string | null {
  if (c.operationalStatus !== "AVAILABLE") return "Контейнер не на стоке";
  if (c.techStatus !== "SOUND") {
    const label = isOneOf(TECH_STATUSES, c.techStatus) ? TECH_STATUS_LABELS[c.techStatus] : c.techStatus;
    return `Тех. статус «${label}»`;
  }
  const csc = cscStateOf(c.cscPlateExpiry, now);
  if (csc.level === "EXPIRED") return `КБК (CSC) просрочена на ${-csc.daysLeft} дн.`;
  return null;
}

export interface StorageInput {
  operationalStatus: string;
  storageStartDate: Date | null;
  storageRatePerDayUsd: number | null;
}

export interface StorageState {
  /** Дней на стоке (null — контейнер не на стоке). */
  idleDays: number | null;
  isIdleTooLong: boolean;
  /** Накопленная стоимость хранения, USD. */
  storageCostUsd: number;
}

export function storageStateOf(container: StorageInput, now: Date): StorageState {
  const onStock = container.operationalStatus === "AVAILABLE" && container.storageStartDate !== null;
  if (!onStock || !container.storageStartDate) {
    return { idleDays: null, isIdleTooLong: false, storageCostUsd: 0 };
  }
  const idleDays = Math.max(0, diffDays(container.storageStartDate, now));
  return {
    idleDays,
    isIdleTooLong: idleDays > THRESHOLDS.idleStockDays,
    storageCostUsd: idleDays * (container.storageRatePerDayUsd ?? 0),
  };
}

export interface EconomicsInput {
  purchasePriceUsd: number;
  currentBookValueUsd: number;
  totalRevenueUsd: number;
  totalRepairCostUsd: number;
}

export interface UnitEconomics {
  depreciationUsd: number;
  /** Выручка − ремонты − амортизация. */
  netResultUsd: number;
  /** netResult / цена покупки. */
  roi: number;
  /** Окупаемость: доля цены покупки, покрытая чистой выручкой (выручка − ремонты). */
  paybackRatio: number;
}

export function unitEconomicsOf(c: EconomicsInput): UnitEconomics {
  const depreciationUsd = Math.max(0, c.purchasePriceUsd - c.currentBookValueUsd);
  const netResultUsd = c.totalRevenueUsd - c.totalRepairCostUsd - depreciationUsd;
  const roi = c.purchasePriceUsd > 0 ? netResultUsd / c.purchasePriceUsd : 0;
  const paybackRatio = c.purchasePriceUsd > 0 ? (c.totalRevenueUsd - c.totalRepairCostUsd) / c.purchasePriceUsd : 0;
  return { depreciationUsd, netResultUsd, roi, paybackRatio };
}

export interface AttentionInput extends StorageInput {
  techStatus: string;
  cscPlateExpiry: Date;
}

export interface AttentionFlags {
  csc: CscState;
  storage: StorageState;
  needsRepair: boolean;
  any: boolean;
}

export function attentionFlagsOf(c: AttentionInput, now: Date): AttentionFlags {
  const csc = cscStateOf(c.cscPlateExpiry, now);
  const storage = storageStateOf(c, now);
  const needsRepair = c.techStatus === "DAMAGED" || c.techStatus === "IN_REPAIR";
  return { csc, storage, needsRepair, any: csc.level !== "OK" || storage.isIdleTooLong || needsRepair };
}
/**
 * Работа с датами на уровне суток (UTC). Даты-«дни» хранятся как полночь UTC,
 * поэтому разница в днях не зависит от часового пояса сервера.
 */

export const DAY_MS = 86_400_000;

export function startOfDayUtc(date: Date): Date {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
}

export function addDays(date: Date, days: number): Date {
  return new Date(date.getTime() + days * DAY_MS);
}

/** +N месяцев; 31.01 + 1 мес. = 28.02 (29.02), а не 03.03 — день ограничивается длиной целевого месяца. */
export function addMonths(date: Date, months: number): Date {
  const target = new Date(date.getTime());
  target.setUTCDate(1);
  target.setUTCMonth(target.getUTCMonth() + months);
  target.setUTCDate(Math.min(date.getUTCDate(), daysInMonthUtc(target)));
  return target;
}

/** Восточный край работы компании — Владивосток (UTC+10). */
const EASTERNMOST_UTC_OFFSET_HOURS = 10;

/**
 * Последняя календарная дата, которая уже наступила хотя бы у одного пользователя.
 * Сервер работает в UTC: без этого во Владивостоке до 10:00 «сегодня» отклонялось бы как дата в будущем.
 */
export function latestBusinessDate(now: Date): Date {
  return startOfDayUtc(new Date(now.getTime() + EASTERNMOST_UTC_OFFSET_HOURS * 3_600_000));
}

/** Сегодняшняя дата по часам пользователя → "2026-10-27" для <input type="date"> (только клиентский код). */
export function toLocalDateInput(date: Date = new Date()): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/** Количество полных суток от `from` до `to` (отрицательное, если `to` раньше). */
export function diffDays(from: Date, to: Date): number {
  return Math.round((startOfDayUtc(to).getTime() - startOfDayUtc(from).getTime()) / DAY_MS);
}

export function startOfMonthUtc(date: Date): Date {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1));
}

export function daysInMonthUtc(date: Date): number {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0)).getUTCDate();
}

/** "2026-10-26" → полночь UTC. Возвращает null для невалидной строки. */
export function parseDateInput(value: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(`${value}T00:00:00.000Z`);
  return Number.isNaN(date.getTime()) ? null : date;
}

/** Дата → "2026-10-26" для <input type="date">. */
export function toDateInput(date: Date | string): string {
  return new Date(date).toISOString().slice(0, 10);
}
/**
 * Форматирование без зависимости от ICU — одинаковый вывод на сервере и в браузере
 * (исключает рассинхрон гидрации из-за разных пробелов-разделителей).
 */

const THIN_SPACE = " ";

function groupThousands(integer: string): string {
  return integer.replace(/\B(?=(\d{3})+(?!\d))/g, THIN_SPACE);
}

export function formatNumber(value: number, fractionDigits = 0): string {
  const sign = value < 0 ? "−" : "";
  const [integer, fraction] = Math.abs(value).toFixed(fractionDigits).split(".");
  return `${sign}${groupThousands(integer)}${fraction ? `,${fraction}` : ""}`;
}

/** $1 234 или $2,50 — копейки показываются, только если они есть или явно запрошены. */
export function formatUsd(value: number, fractionDigits?: number): string {
  const digits = fractionDigits ?? (Number.isInteger(value) ? 0 : 2);
  const sign = value < 0 ? "−" : "";
  return `${sign}$${formatNumber(Math.abs(value), digits)}`;
}

export function formatPercent(value: number, fractionDigits = 0): string {
  return `${formatNumber(value * 100, fractionDigits)}%`;
}

const MONTHS_SHORT = ["янв", "фев", "мар", "апр", "мая", "июн", "июл", "авг", "сен", "окт", "ноя", "дек"];

function pad(value: number): string {
  return String(value).padStart(2, "0");
}

/** Дата-«день» (полночь UTC): 26.10.2026 */
export function formatDate(value: Date | string | null | undefined): string {
  if (!value) return "—";
  const d = new Date(value);
  return `${pad(d.getUTCDate())}.${pad(d.getUTCMonth() + 1)}.${d.getUTCFullYear()}`;
}

/** Короткая дата: 26 окт 2026 */
export function formatDateShort(value: Date | string | null | undefined): string {
  if (!value) return "—";
  const d = new Date(value);
  return `${d.getUTCDate()} ${MONTHS_SHORT[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

const MOSCOW_OFFSET_MS = 3 * 3_600_000;

/** Дата и время события по Москве: 26.10.2026 14:30 */
export function formatDateTime(value: Date | string): string {
  const d = new Date(new Date(value).getTime() + MOSCOW_OFFSET_MS);
  return `${formatDate(d)} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`;
}

/** Склонение: plural(5, ["день", "дня", "дней"]) → "дней" */
export function plural(n: number, forms: readonly [string, string, string]): string {
  const abs = Math.abs(n) % 100;
  const last = abs % 10;
  if (abs > 10 && abs < 20) return forms[2];
  if (last > 1 && last < 5) return forms[1];
  if (last === 1) return forms[0];
  return forms[2];
}

export function formatDays(n: number): string {
  return `${n} ${plural(n, ["день", "дня", "дней"])}`;
}

