import "server-only";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireSession } from "@/lib/auth/dal";
import type { SessionPayload } from "@/lib/auth/session";
import { can, type Permission } from "@/lib/auth/permissions";
import { parseDateInput } from "@/lib/dates";
import type { ActionResult } from "./types";

export type Parsed<T> = { ok: true; data: T } | { ok: false; result: ActionResult };

export type Authorized = { ok: true; session: SessionPayload } | { ok: false; result: ActionResult };

/**
 * Сессия + право на действие. Роль читается из БД, а не из JWT: понижение роли или удаление
 * пользователя действует сразу, не дожидаясь истечения 8-часового токена.
 */
export async function authorize(permission: Permission): Promise<Authorized> {
  const session = await requireSession();
  const user = await prisma.user.findUnique({ where: { id: session.userId }, select: { role: true, name: true } });
  if (!user) return { ok: false, result: { ok: false, error: "Учётная запись не найдена — войдите заново" } };
  if (!can(user.role, permission)) return { ok: false, result: { ok: false, error: "Недостаточно прав для этого действия" } };
  return { ok: true, session: { ...session, role: user.role, name: user.name } };
}

/** Состояние записи изменил параллельный запрос (двойной клик, второй сотрудник) — операция не выполнена. */
export class ConflictError extends Error {}

export function parseInput<S extends z.ZodType>(schema: S, input: unknown): Parsed<z.infer<S>> {
  const parsed = schema.safeParse(input);
  if (parsed.success) return { ok: true, data: parsed.data };
  const fieldErrors: Record<string, string> = {};
  for (const issue of parsed.error.issues) {
    const key = issue.path.join(".") || "_";
    if (!fieldErrors[key]) fieldErrors[key] = issue.message;
  }
  return { ok: false, result: { ok: false, error: parsed.error.issues[0]?.message ?? "Проверьте данные формы", fieldErrors } };
}

/** "2026-10-26" → Date (полночь UTC). */
export const dateField = z
  .string({ error: "Укажите дату" })
  .refine((v) => parseDateInput(v) !== null, "Некорректная дата")
  .transform((v) => parseDateInput(v) as Date);

export const moneyField = z.coerce.number({ error: "Введите число" }).min(0, "Не может быть отрицательным").max(10_000_000, "Слишком большое значение");

export const optionalText = (max = 500) =>
  z
    .string()
    .trim()
    .max(max, `Не более ${max} символов`)
    .optional()
    .transform((v) => (v ? v : null));

export const requiredText = (label: string, max = 200) => z.string({ error: `Укажите: ${label}` }).trim().min(1, `Укажите: ${label}`).max(max);

export const locodeField = z
  .string()
  .trim()
  .toUpperCase()
  .regex(/^[A-Z]{2}[A-Z2-9]{3}$/, "UN/LOCODE: 5 символов, например RUVVO");

export const innField = z
  .string()
  .trim()
  .regex(/^(\d{10}|\d{12})?$/, "ИНН: 10 или 12 цифр")
  .optional()
  .transform((v) => (v ? v : null));

/**
 * Неожиданная ошибка: подробности — только в серверный лог, пользователю — общий текст.
 * Нарушение уникальности (гонка двух одновременных запросов) переводится в понятное сообщение.
 */
export function serverError(context: string, error: unknown): ActionResult {
  if (error instanceof ConflictError) return { ok: false, error: error.message };
  const code = typeof error === "object" && error !== null && "code" in error ? String((error as { code: unknown }).code) : null;
  if (code === "P2002") return { ok: false, error: "Запись с таким номером уже существует" };
  console.error(`[action:${context}]`, error);
  return { ok: false, error: "Не удалось сохранить изменения. Повторите попытку или обратитесь к администратору." };
}

export function notFound(entity: string): ActionResult {
  return { ok: false, error: `${entity} не найден(а) — возможно, данные были сброшены` };
}
export type ActionResult =
  | { ok: true; message: string; id?: string }
  | { ok: false; error: string; fieldErrors?: Record<string, string> };
"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { computeDeadline, computeTripTiming } from "@/lib/domain/one-way";
import { locodeCity } from "@/lib/domain/constants";
import { issueBlockReason } from "@/lib/domain/container";
import { formatBic } from "@/lib/iso6346";
import { formatDate, formatUsd } from "@/lib/format";
import { latestBusinessDate, startOfDayUtc } from "@/lib/dates";
import { authorize, ConflictError, dateField, innField, locodeField, moneyField, notFound, optionalText, parseInput, requiredText, serverError } from "./helpers";
import type { ActionResult } from "./types";

const createTripSchema = z.object({
  containerId: z.string().min(1, "Выберите контейнер"),
  counterpartyName: requiredText("контрагент", 200),
  counterpartyInn: innField,
  counterpartyContact: optionalText(200),
  bookingRef: requiredText("номер заявки/договора", 60),
  dropoffLocode: locodeField,
  dropoffTerminal: requiredText("депо возврата", 120),
  handoverDate: dateField,
  freeDays: z.coerce.number().int().min(1, "Минимум 1 день").max(365, "Не более 365 дней"),
  feeUsd: moneyField,
  detentionRatePerDayUsd: moneyField,
  notes: optionalText(1000),
});

export type CreateTripInput = z.input<typeof createTripSchema>;

export async function createOneWayAction(input: CreateTripInput): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(createTripSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;

  const container = await prisma.container.findUnique({ where: { id: data.containerId } });
  if (!container) return notFound("Контейнер");
  const blockReason = issueBlockReason(container, new Date());
  if (blockReason) {
    return { ok: false, error: `${formatBic(container.bicCode)}: выдача запрещена — ${blockReason}`, fieldErrors: { containerId: blockReason } };
  }

  const deadline = computeDeadline(data.handoverDate, data.freeDays);
  try {
    const trip = await prisma.$transaction(async (tx) => {
      // Захват контейнера условием «ещё на стоке»: параллельная выдача того же контейнера получит count = 0.
      const claimed = await tx.container.updateMany({
        where: { id: container.id, operationalStatus: "AVAILABLE" },
        data: { operationalStatus: "ONE_WAY", currentTerminal: `Выдан: ${data.counterpartyName}`, storageStartDate: null, totalRevenueUsd: { increment: data.feeUsd } },
      });
      if (claimed.count === 0) throw new ConflictError(`${formatBic(container.bicCode)} уже выдан или снят со стока — обновите страницу`);
      const created = await tx.oneWayTrip.create({
        data: {
          containerId: container.id,
          counterpartyName: data.counterpartyName,
          counterpartyInn: data.counterpartyInn,
          counterpartyContact: data.counterpartyContact,
          bookingRef: data.bookingRef,
          pickupLocode: container.currentLocode,
          pickupTerminal: container.currentTerminal,
          dropoffLocode: data.dropoffLocode,
          dropoffTerminal: data.dropoffTerminal,
          handoverDate: data.handoverDate,
          freeDays: data.freeDays,
          deadlineDate: deadline,
          feeUsd: data.feeUsd,
          detentionRatePerDayUsd: data.detentionRatePerDayUsd,
          status: "ACTIVE",
          notes: data.notes,
        },
      });
      await tx.containerEvent.create({
        data: {
          containerId: container.id,
          type: "ONE_WAY_OUT",
          occurredAt: new Date(),
          locode: container.currentLocode,
          terminal: container.currentTerminal,
          description: `Gate-Out: выдан в One-Way ${data.bookingRef} контрагенту ${data.counterpartyName}. Возврат: ${locodeCity(data.dropoffLocode)}, ${data.dropoffTerminal} до ${formatDate(deadline)} (${data.freeDays} своб. дней), детеншн ${formatUsd(data.detentionRatePerDayUsd)}/сут.`,
          amountUsd: data.feeUsd || null,
          actor: session.name,
        },
      });
      return created;
    });
    revalidatePath("/", "layout");
    return { ok: true, message: `${formatBic(container.bicCode)} выдан в One-Way до ${formatDate(deadline)}`, id: trip.id };
  } catch (error) {
    return serverError("one-way", error);
  }
}

const returnSchema = z
  .object({
    returnDate: dateField,
    terminal: requiredText("терминал приёмки", 120),
    condition: z.enum(["SOUND", "DAMAGED"]),
    eorUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
    note: optionalText(1000),
  })
  .superRefine((v, ctx) => {
    if (v.condition === "DAMAGED" && !v.eorUsd) ctx.addIssue({ code: "custom", path: ["eorUsd"], message: "Укажите оценку ремонта (EOR)" });
  });

export type TripReturnInput = z.input<typeof returnSchema>;

/** Gate-In по One-Way: закрывает рейс, начисляет детеншн, ставит контейнер на сток депо назначения. */
export async function registerOneWayReturnAction(tripId: string, input: TripReturnInput): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(returnSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;

  const trip = await prisma.oneWayTrip.findUnique({ where: { id: tripId }, include: { container: true } });
  if (!trip) return notFound("Рейс One-Way");
  if (trip.status !== "ACTIVE") return { ok: false, error: "Возврат по этому рейсу уже зафиксирован" };
  if (data.returnDate < startOfDayUtc(trip.handoverDate)) return { ok: false, error: "Дата возврата раньше даты выдачи", fieldErrors: { returnDate: "Раньше даты выдачи" } };
  if (data.returnDate > latestBusinessDate(new Date())) return { ok: false, error: "Дата возврата не может быть в будущем", fieldErrors: { returnDate: "Дата в будущем" } };

  const timing = computeTripTiming({ ...trip, status: "COMPLETED", actualReturnDate: data.returnDate }, new Date());
  const isDamaged = data.condition === "DAMAGED";
  const detentionNote = timing.overdueDays > 0 ? ` Просрочка ${timing.overdueDays} дн., начислен детеншн ${formatUsd(timing.detentionUsd)}.` : " Возврат в пределах свободных дней.";

  try {
    await prisma.$transaction(async (tx) => {
      // Закрываем рейс условием status = ACTIVE: второй параллельный Gate-In получит count = 0 и не начислит детеншн повторно.
      const closed = await tx.oneWayTrip.updateMany({
        where: { id: trip.id, status: "ACTIVE" },
        data: {
          status: isDamaged ? "DISPUTE" : "COMPLETED",
          actualReturnDate: data.returnDate,
          dropoffTerminal: data.terminal,
          returnCondition: data.condition,
          returnEorUsd: isDamaged ? data.eorUsd : null,
          notes: data.note ?? trip.notes,
        },
      });
      if (closed.count === 0) throw new ConflictError("Возврат по этому рейсу уже зафиксирован");
      await tx.container.update({
        where: { id: trip.containerId },
        data: {
          operationalStatus: "AVAILABLE",
          currentLocode: trip.dropoffLocode,
          currentTerminal: data.terminal,
          storageStartDate: data.returnDate,
          techStatus: isDamaged ? "DAMAGED" : trip.container.techStatus,
          conditionGrade: isDamaged ? "DAMAGED" : trip.container.conditionGrade,
          eorAmountUsd: isDamaged ? data.eorUsd : trip.container.eorAmountUsd,
          totalRevenueUsd: { increment: timing.detentionUsd },
          events: {
            create: [
              {
                type: "ONE_WAY_IN",
                occurredAt: new Date(),
                locode: trip.dropoffLocode,
                terminal: data.terminal,
                description: `Gate-In по One-Way ${trip.bookingRef} (${trip.counterpartyName}).${detentionNote}${isDamaged ? ` Повреждение при приёмке, открыта претензия (EOR ${formatUsd(data.eorUsd ?? 0)}).` : " Состояние: исправен."}${data.note ? ` ${data.note}` : ""}`,
                amountUsd: timing.detentionUsd || null,
                actor: session.name,
              },
              ...(isDamaged
                ? [{ type: "INSPECTION", occurredAt: new Date(), locode: trip.dropoffLocode, terminal: data.terminal, description: `Акт осмотра при приёмке: повреждение. EOR ${formatUsd(data.eorUsd ?? 0)}.`, amountUsd: data.eorUsd, actor: session.name }]
                : []),
            ],
          },
        },
      });
    });
    revalidatePath("/", "layout");
    return {
      ok: true,
      message: `${formatBic(trip.container.bicCode)} принят на ${data.terminal}.${timing.detentionUsd > 0 ? ` Детеншн: ${formatUsd(timing.detentionUsd)}.` : ""}${isDamaged ? " Открыта претензия." : ""}`,
    };
  } catch (error) {
    return serverError("one-way", error);
  }
}

const resolveSchema = z.object({ compensationUsd: moneyField, note: optionalText(500) });

export async function resolveDisputeAction(tripId: string, input: z.input<typeof resolveSchema>): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(resolveSchema, input);
  if (!parsed.ok) return parsed.result;
  const trip = await prisma.oneWayTrip.findUnique({ where: { id: tripId }, include: { container: { select: { bicCode: true, currentLocode: true, currentTerminal: true } } } });
  if (!trip) return notFound("Рейс One-Way");
  if (trip.status !== "DISPUTE") return { ok: false, error: "По рейсу нет открытой претензии" };

  const { compensationUsd, note } = parsed.data;
  try {
    await prisma.$transaction(async (tx) => {
      const closed = await tx.oneWayTrip.updateMany({
        where: { id: tripId, status: "DISPUTE" },
        data: { status: "COMPLETED", notes: [trip.notes, `Претензия закрыта: компенсация ${formatUsd(compensationUsd)}. ${note ?? ""}`].filter(Boolean).join("\n") },
      });
      if (closed.count === 0) throw new ConflictError("Претензия уже закрыта");
      await tx.container.update({
        where: { id: trip.containerId },
        data: {
          totalRevenueUsd: { increment: compensationUsd },
          events: {
            create: {
              type: "STATUS_CHANGE",
              occurredAt: new Date(),
              locode: trip.container.currentLocode,
              terminal: trip.container.currentTerminal,
              description: `Претензия по One-Way ${trip.bookingRef} урегулирована: компенсация ${formatUsd(compensationUsd)} от ${trip.counterpartyName}.${note ? ` ${note}` : ""}`,
              amountUsd: compensationUsd || null,
              actor: session.name,
            },
          },
        },
      });
    });
  } catch (error) {
    return serverError("one-way", error);
  }
  revalidatePath("/", "layout");
  return { ok: true, message: `Претензия по ${trip.bookingRef} закрыта` };
}
"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { addMonths, latestBusinessDate, startOfDayUtc } from "@/lib/dates";
import { PAYMENT_STATUSES, PAYMENT_STATUS_LABELS, locodeCity } from "@/lib/domain/constants";
import { parseLocodeList, rentalDaysInRange } from "@/lib/domain/lease";
import { issueBlockReason } from "@/lib/domain/container";
import { formatBic } from "@/lib/iso6346";
import { formatDate, formatUsd } from "@/lib/format";
import { authorize, ConflictError, dateField, innField, locodeField, moneyField, notFound, optionalText, parseInput, requiredText, serverError } from "./helpers";
import type { ActionResult } from "./types";

const createLeaseSchema = z
  .object({
    contractNumber: requiredText("номер договора", 40),
    lesseeName: requiredText("арендатор", 200),
    lesseeInn: innField,
    contactPerson: requiredText("контактное лицо", 120),
    contactPhone: optionalText(40),
    contactEmail: z.union([z.literal(""), z.string().trim().email("Некорректный email")]).optional().transform((v) => (v ? v : null)),
    startDate: dateField,
    endDate: dateField,
    autoRenewal: z.boolean(),
    dailyRateUsd: z.coerce.number().positive("Ставка должна быть больше 0").max(1000),
    depositUsd: moneyField,
    allowedReturnLocodes: z.array(locodeField).min(1, "Выберите хотя бы один регион возврата"),
    containerIds: z.array(z.string().min(1)).min(1, "Добавьте хотя бы один контейнер"),
    notes: optionalText(1000),
  })
  .superRefine((v, ctx) => {
    if (v.endDate <= v.startDate) ctx.addIssue({ code: "custom", path: ["endDate"], message: "Окончание должно быть позже начала" });
  });

export type CreateLeaseInput = z.input<typeof createLeaseSchema>;

export async function createLeaseAction(input: CreateLeaseInput): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(createLeaseSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;

  const duplicate = await prisma.leaseContract.findUnique({ where: { contractNumber: data.contractNumber }, select: { id: true } });
  if (duplicate) return { ok: false, error: "Договор с таким номером уже существует", fieldErrors: { contractNumber: "Номер занят" } };

  const containers = await prisma.container.findMany({ where: { id: { in: data.containerIds } } });
  const now = new Date();
  if (containers.length !== data.containerIds.length) return { ok: false, error: "Часть контейнеров не найдена — обновите страницу" };
  const blocked = containers.map((c) => ({ c, reason: issueBlockReason(c, now) })).filter((x) => x.reason !== null);
  if (blocked.length > 0) {
    return {
      ok: false,
      error: `Выдача в аренду запрещена: ${blocked.map((x) => `${formatBic(x.c.bicCode)} — ${x.reason}`).join("; ")}`,
      fieldErrors: { containerIds: "Есть заблокированные контейнеры" },
    };
  }

  try {
    const lease = await prisma.$transaction(async (tx) => {
      const created = await tx.leaseContract.create({
        data: {
          contractNumber: data.contractNumber,
          lesseeName: data.lesseeName,
          lesseeInn: data.lesseeInn,
          contactPerson: data.contactPerson,
          contactPhone: data.contactPhone,
          contactEmail: data.contactEmail,
          startDate: data.startDate,
          endDate: data.endDate,
          autoRenewal: data.autoRenewal,
          dailyRateUsd: data.dailyRateUsd,
          depositUsd: data.depositUsd,
          paymentStatus: "PENDING",
          allowedReturnLocodes: data.allowedReturnLocodes.join(","),
          onHireSurvey: "SIGNED",
          offHireSurvey: "NOT_STARTED",
          status: "ACTIVE",
          notes: data.notes,
          items: { create: containers.map((c) => ({ containerId: c.id, onHireDate: data.startDate })) },
        },
      });
      for (const c of containers) {
        // Захват условием «ещё на стоке»: контейнер, параллельно выданный в другой договор/рейс, откатит всю транзакцию.
        const claimed = await tx.container.updateMany({
          where: { id: c.id, operationalStatus: "AVAILABLE" },
          data: { operationalStatus: "LONG_TERM_LEASE", currentTerminal: `В аренде: ${data.lesseeName}`, storageStartDate: null },
        });
        if (claimed.count === 0) throw new ConflictError(`${formatBic(c.bicCode)} уже выдан или снят со стока — обновите страницу`);
        await tx.container.update({
          where: { id: c.id },
          data: {
            events: {
              create: {
                type: "LEASE_ON_HIRE",
                occurredAt: new Date(),
                locode: c.currentLocode,
                terminal: c.currentTerminal,
                description: `On-Hire: передан в аренду ${data.lesseeName} по договору ${data.contractNumber} (с ${formatDate(data.startDate)} по ${formatDate(data.endDate)}), Per Diem ${formatUsd(data.dailyRateUsd, 2)}. On-Hire Survey подписан.`,
                actor: session.name,
              },
            },
          },
        });
      }
      return created;
    });
    revalidatePath("/", "layout");
    return { ok: true, message: `Договор ${data.contractNumber} оформлен: ${containers.length} ед.`, id: lease.id };
  } catch (error) {
    return serverError("leases", error);
  }
}

const extendSchema = z.object({
  months: z.coerce.number().int().min(1, "Минимум 1 месяц").max(60, "Не более 60 месяцев"),
  newDailyRateUsd: z.union([z.coerce.number().positive().max(1000), z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
});

export async function extendLeaseAction(leaseId: string, input: z.input<typeof extendSchema>): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(extendSchema, input);
  if (!parsed.ok) return parsed.result;
  const lease = await prisma.leaseContract.findUnique({ where: { id: leaseId }, include: { items: { where: { offHireDate: null }, include: { container: true } } } });
  if (!lease) return notFound("Договор");
  if (lease.status !== "ACTIVE") return { ok: false, error: "Договор уже закрыт" };

  const { months, newDailyRateUsd } = parsed.data;
  // Ставка хранится одна на договор: смена Per Diem пересчитала бы задним числом уже начисленные дни
  // (Off-Hire, «Начислено за срок», CSV). Новая ставка оформляется новым договором.
  if (newDailyRateUsd !== null && newDailyRateUsd !== lease.dailyRateUsd) {
    return {
      ok: false,
      error: "Изменение ставки при продлении не поддерживается: оформите новый договор с новой ставкой",
      fieldErrors: { newDailyRateUsd: "Ставка меняется новым договором" },
    };
  }
  const newEnd = addMonths(lease.endDate, months);
  await prisma.$transaction([
    prisma.leaseContract.update({
      where: { id: leaseId },
      data: { endDate: newEnd, offHireSurvey: "NOT_STARTED" },
    }),
    prisma.containerEvent.createMany({
      data: lease.items.map((item) => ({
        containerId: item.containerId,
        type: "LEASE_EXTENDED",
        occurredAt: new Date(),
        locode: item.container.currentLocode,
        terminal: item.container.currentTerminal,
        description: `Договор ${lease.contractNumber} продлён на ${months} мес. до ${formatDate(newEnd)}.`,
        actor: session.name,
      })),
    }),
  ]);
  revalidatePath("/", "layout");
  return { ok: true, message: `Договор ${lease.contractNumber} продлён до ${formatDate(newEnd)}` };
}

const offHireSchema = z
  .object({
    itemIds: z.array(z.string().min(1)).min(1, "Выберите контейнеры для возврата"),
    returnDate: dateField,
    returnLocode: locodeField,
    terminal: requiredText("депо возврата", 120),
    condition: z.enum(["SOUND", "DAMAGED"]),
    eorUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
  })
  .superRefine((v, ctx) => {
    if (v.condition === "DAMAGED" && !v.eorUsd) ctx.addIssue({ code: "custom", path: ["eorUsd"], message: "Укажите оценку ремонта (EOR)" });
  });

export type OffHireInput = z.input<typeof offHireSchema>;

export async function offHireAction(leaseId: string, input: OffHireInput): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(offHireSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;

  const lease = await prisma.leaseContract.findUnique({ where: { id: leaseId }, include: { items: { include: { container: true } } } });
  if (!lease) return notFound("Договор");
  if (!parseLocodeList(lease.allowedReturnLocodes).includes(data.returnLocode)) {
    return { ok: false, error: `${locodeCity(data.returnLocode)} не входит в разрешённые регионы возврата`, fieldErrors: { returnLocode: "Не разрешено договором" } };
  }
  const items = lease.items.filter((i) => data.itemIds.includes(i.id) && !i.offHireDate);
  if (items.length !== data.itemIds.length) return { ok: false, error: "Часть контейнеров уже возвращена или не относится к договору" };
  if (items.some((i) => data.returnDate < startOfDayUtc(i.onHireDate))) return { ok: false, error: "Дата возврата раньше даты On-Hire", fieldErrors: { returnDate: "Раньше On-Hire" } };
  if (data.returnDate > latestBusinessDate(new Date())) return { ok: false, error: "Дата возврата не может быть в будущем", fieldErrors: { returnDate: "Дата в будущем" } };

  const remaining = lease.items.filter((i) => !i.offHireDate).length - items.length;
  const isDamaged = data.condition === "DAMAGED";

  try {
    await prisma.$transaction(async (tx) => {
      for (const item of items) {
        const rentalDays = rentalDaysInRange({ onHireDate: item.onHireDate, offHireDate: data.returnDate }, item.onHireDate, data.returnDate);
        const earned = rentalDays * lease.dailyRateUsd;
        // Условие offHireDate = null: единица, уже возвращённая параллельным запросом, не принесёт выручку повторно.
        const returned = await tx.leaseItem.updateMany({ where: { id: item.id, offHireDate: null }, data: { offHireDate: data.returnDate, returnLocode: data.returnLocode } });
        if (returned.count === 0) throw new ConflictError("Часть контейнеров уже возвращена — обновите страницу");
        await tx.container.update({
          where: { id: item.containerId },
          data: {
            operationalStatus: "AVAILABLE",
            currentLocode: data.returnLocode,
            currentTerminal: data.terminal,
            storageStartDate: data.returnDate,
            techStatus: isDamaged ? "DAMAGED" : item.container.techStatus,
            conditionGrade: isDamaged ? "DAMAGED" : item.container.conditionGrade,
            eorAmountUsd: isDamaged ? data.eorUsd : item.container.eorAmountUsd,
            totalRevenueUsd: { increment: earned },
            events: {
              create: {
                type: "LEASE_OFF_HIRE",
                occurredAt: new Date(),
                locode: data.returnLocode,
                terminal: data.terminal,
                description: `Off-Hire по договору ${lease.contractNumber}: возвращен на ${data.terminal} (${locodeCity(data.returnLocode)}). Аренда ${rentalDays} сут. × ${formatUsd(lease.dailyRateUsd, 2)} = ${formatUsd(earned)}. Off-Hire Survey: ${isDamaged ? `повреждение, EOR ${formatUsd(data.eorUsd ?? 0)}` : "без замечаний"}.`,
                amountUsd: earned,
                actor: session.name,
              },
            },
          },
        });
      }
      await tx.leaseContract.update({
        where: { id: leaseId },
        data: remaining === 0 ? { status: "COMPLETED", offHireSurvey: "SIGNED" } : { offHireSurvey: "PENDING" },
      });
    });
    revalidatePath("/", "layout");
    return { ok: true, message: `Off-Hire оформлен: ${items.length} ед.${remaining === 0 ? " Договор закрыт." : ` На руках у арендатора: ${remaining}.`}` };
  } catch (error) {
    return serverError("leases", error);
  }
}

const paymentSchema = z.object({ paymentStatus: z.enum(PAYMENT_STATUSES) });

export async function updatePaymentStatusAction(leaseId: string, input: z.input<typeof paymentSchema>): Promise<ActionResult> {
  const auth = await authorize("operations:manage");
  if (!auth.ok) return auth.result;
  const parsed = parseInput(paymentSchema, input);
  if (!parsed.ok) return parsed.result;
  const lease = await prisma.leaseContract.findUnique({ where: { id: leaseId }, select: { id: true, contractNumber: true } });
  if (!lease) return notFound("Договор");
  await prisma.leaseContract.update({ where: { id: leaseId }, data: { paymentStatus: parsed.data.paymentStatus } });
  revalidatePath("/", "layout");
  return { ok: true, message: `${lease.contractNumber}: статус оплаты — «${PAYMENT_STATUS_LABELS[parsed.data.paymentStatus]}»` };
}

toolUseResult.stdout:
"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { validateBic, formatBic } from "@/lib/iso6346";
import { startOfDayUtc } from "@/lib/dates";
import {
  CONDITION_GRADES,
  EVENT_TYPES,
  OPERATIONAL_STATUSES,
  SIZE_TYPES,
  TECH_STATUSES,
  OPERATIONAL_STATUS_LABELS,
  TECH_STATUS_LABELS,
} from "@/lib/domain/constants";
import { authorize, dateField, locodeField, moneyField, notFound, optionalText, parseInput, requiredText, serverError } from "./helpers";
import type { ActionResult } from "./types";

const baseContainerSchema = z.object({
  bicCode: z.string().trim(),
  sizeType: z.enum(SIZE_TYPES, { error: "Выберите типоразмер" }),
  isoCode: z.string().trim().toUpperCase().regex(/^[0-9A-Z]{4}$/, "ISO-код типа: 4 символа, например 45G1"),
  manufactureYear: z.coerce.number().int().min(1990, "Год не ранее 1990").max(new Date().getUTCFullYear() + 1, "Год из будущего"),
  colorRal: requiredText("цвет RAL", 60),
  manufacturer: requiredText("завод-изготовитель", 120),
  tareWeightKg: z.coerce.number().int().min(500, "Тара от 500 кг").max(15_000),
  maxGrossWeightKg: z.coerce.number().int().min(10_000).max(60_000),
  conditionGrade: z.enum(CONDITION_GRADES),
  techStatus: z.enum(TECH_STATUSES),
  cscPlateExpiry: dateField,
  eorAmountUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
  operationalStatus: z.enum(OPERATIONAL_STATUSES),
  currentLocode: locodeField,
  currentTerminal: requiredText("терминал / депо", 120),
  storageRatePerDayUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
  purchaseDate: dateField,
  purchasePriceUsd: moneyField,
  currentBookValueUsd: moneyField,
  notes: optionalText(1000),
});

const containerSchema = baseContainerSchema.superRefine((value, ctx) => {
  const bic = validateBic(value.bicCode);
  if (!bic.valid) ctx.addIssue({ code: "custom", path: ["bicCode"], message: bic.errors[0] ?? "Некорректный номер" });
  if (value.tareWeightKg >= value.maxGrossWeightKg) {
    ctx.addIssue({ code: "custom", path: ["tareWeightKg"], message: "Тара должна быть меньше брутто" });
  }
  if (value.currentBookValueUsd > value.purchasePriceUsd) {
    ctx.addIssue({ code: "custom", path: ["currentBookValueUsd"], message: "Остаточная стоимость не может превышать цену покупки" });
  }
});

export type ContainerInput = z.input<typeof baseContainerSchema>;

/** Операционные статусы, которые управляются только через модули One-Way / аренды. */
const MANAGED_STATUSES = new Set(["ONE_WAY", "LONG_TERM_LEASE"]);

export async function createContainerAction(input: ContainerInput): Promise<ActionResult> {
  const auth = await authorize("fleet:edit");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(containerSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;
  if (MANAGED_STATUSES.has(data.operationalStatus)) {
    return { ok: false, error: "Статусы One-Way и аренды назначаются через соответствующие модули", fieldErrors: { operationalStatus: "Недоступно при создании" } };
  }
  const bicCode = validateBic(data.bicCode).normalized;

  const exists = await prisma.container.findUnique({ where: { bicCode }, select: { id: true } });
  if (exists) return { ok: false, error: `Контейнер ${formatBic(bicCode)} уже есть в реестре`, fieldErrors: { bicCode: "Номер уже существует" } };

  try {
    const now = new Date();
    const container = await prisma.container.create({
      data: {
        ...data,
        bicCode,
        maxPayloadKg: data.maxGrossWeightKg - data.tareWeightKg,
        storageStartDate: data.operationalStatus === "AVAILABLE" ? startOfDayUtc(now) : null,
        events: {
          create: [
            {
              type: "PURCHASE",
              occurredAt: now,
              locode: data.currentLocode,
              terminal: data.currentTerminal,
              description: `Контейнер введён в реестр. Покупка ${data.purchaseDate.toISOString().slice(0, 10)} у ${data.manufacturer}.`,
              amountUsd: data.purchasePriceUsd,
              actor: session.name,
            },
          ],
        },
      },
    });
    revalidatePath("/", "layout");
    return { ok: true, message: `Контейнер ${formatBic(bicCode)} добавлен в парк`, id: container.id };
  } catch (error) {
    return serverError("containers", error);
  }
}

export async function updateContainerAction(id: string, input: ContainerInput): Promise<ActionResult> {
  const auth = await authorize("fleet:edit");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(containerSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;
  const bicCode = validateBic(data.bicCode).normalized;

  const current = await prisma.container.findUnique({ where: { id } });
  if (!current) return notFound("Контейнер");

  const statusChangedToManaged = data.operationalStatus !== current.operationalStatus && MANAGED_STATUSES.has(data.operationalStatus);
  const leavingManaged = data.operationalStatus !== current.operationalStatus && MANAGED_STATUSES.has(current.operationalStatus);
  if (statusChangedToManaged || leavingManaged) {
    return {
      ok: false,
      error: "Выдача/возврат One-Way и аренды оформляются в соответствующих модулях",
      fieldErrors: { operationalStatus: "Используйте модуль One-Way или «Долгосрочная аренда»" },
    };
  }
  if (bicCode !== current.bicCode) {
    const clash = await prisma.container.findUnique({ where: { bicCode }, select: { id: true } });
    if (clash) return { ok: false, error: "Такой номер уже есть в реестре", fieldErrors: { bicCode: "Номер уже существует" } };
  }

  const changes: string[] = [];
  if (current.techStatus !== data.techStatus) changes.push(`тех. статус: ${TECH_STATUS_LABELS[current.techStatus as keyof typeof TECH_STATUS_LABELS] ?? current.techStatus} → ${TECH_STATUS_LABELS[data.techStatus]}`);
  if (current.operationalStatus !== data.operationalStatus) changes.push(`режим: ${OPERATIONAL_STATUS_LABELS[current.operationalStatus as keyof typeof OPERATIONAL_STATUS_LABELS] ?? current.operationalStatus} → ${OPERATIONAL_STATUS_LABELS[data.operationalStatus]}`);
  if (current.conditionGrade !== data.conditionGrade) changes.push(`грейд: ${current.conditionGrade} → ${data.conditionGrade}`);
  if (current.currentLocode !== data.currentLocode || current.currentTerminal !== data.currentTerminal) changes.push(`локация: ${data.currentLocode}, ${data.currentTerminal}`);

  const becameAvailable = data.operationalStatus === "AVAILABLE" && current.operationalStatus !== "AVAILABLE";
  try {
    await prisma.container.update({
      where: { id },
      data: {
        ...data,
        bicCode,
        maxPayloadKg: data.maxGrossWeightKg - data.tareWeightKg,
        storageStartDate: data.operationalStatus !== "AVAILABLE" ? null : becameAvailable ? startOfDayUtc(new Date()) : current.storageStartDate,
        events: changes.length
          ? {
              create: {
                type: "STATUS_CHANGE",
                occurredAt: new Date(),
                locode: data.currentLocode,
                terminal: data.currentTerminal,
                description: `Карточка обновлена: ${changes.join("; ")}.`,
                actor: session.name,
              },
            }
          : undefined,
      },
    });
    revalidatePath("/", "layout");
    return { ok: true, message: "Карточка контейнера сохранена" };
  } catch (error) {
    return serverError("containers", error);
  }
}

export async function deleteContainerAction(id: string): Promise<ActionResult> {
  const auth = await authorize("fleet:delete");
  if (!auth.ok) return auth.result;
  const container = await prisma.container.findUnique({ where: { id }, select: { bicCode: true, operationalStatus: true } });
  if (!container) return notFound("Контейнер");
  if (MANAGED_STATUSES.has(container.operationalStatus)) {
    return { ok: false, error: "Нельзя удалить контейнер в активном One-Way или аренде — сначала оформите возврат" };
  }
  const openTrip = await prisma.oneWayTrip.findFirst({ where: { containerId: id, status: { in: ["ACTIVE", "DISPUTE"] } }, select: { bookingRef: true } });
  if (openTrip) {
    return { ok: false, error: `По рейсу One-Way ${openTrip.bookingRef} есть незакрытая претензия — сначала урегулируйте её` };
  }
  await prisma.container.delete({ where: { id } });
  revalidatePath("/", "layout");
  return { ok: true, message: `Контейнер ${formatBic(container.bicCode)} списан из реестра` };
}

const eventSchema = z.object({
  type: z.enum(EVENT_TYPES),
  occurredAt: dateField,
  description: requiredText("описание", 1000),
  amountUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
});

export async function addContainerEventAction(containerId: string, input: z.input<typeof eventSchema>): Promise<ActionResult> {
  const auth = await authorize("fleet:edit");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(eventSchema, input);
  if (!parsed.ok) return parsed.result;
  const container = await prisma.container.findUnique({ where: { id: containerId }, select: { currentLocode: true, currentTerminal: true } });
  if (!container) return notFound("Контейнер");
  await prisma.containerEvent.create({
    data: {
      containerId,
      ...parsed.data,
      locode: container.currentLocode,
      terminal: container.currentTerminal,
      actor: session.name,
    },
  });
  revalidatePath(`/containers/${containerId}`);
  return { ok: true, message: "Событие добавлено в журнал" };
}
"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { startOfDayUtc } from "@/lib/dates";
import { CONDITION_GRADES, CONDITION_GRADE_LABELS, TECH_STATUSES, TECH_STATUS_LABELS, locodeCity } from "@/lib/domain/constants";
import { formatBic } from "@/lib/iso6346";
import { issueBlockReason } from "@/lib/domain/container";
import { formatDate, formatUsd } from "@/lib/format";
import { authorize, dateField, locodeField, moneyField, notFound, optionalText, parseInput, requiredText } from "./helpers";
import type { ActionResult } from "./types";

const inspectionSchema = z
  .object({
    conditionGrade: z.enum(CONDITION_GRADES),
    techStatus: z.enum(TECH_STATUSES),
    eorUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
    comment: optionalText(1000),
  })
  .superRefine((v, ctx) => {
    if ((v.techStatus === "DAMAGED" || v.techStatus === "IN_REPAIR") && !v.eorUsd) {
      ctx.addIssue({ code: "custom", path: ["eorUsd"], message: "Для повреждённого контейнера укажите EOR" });
    }
    if (v.techStatus === "SOUND" && v.conditionGrade === "DAMAGED") {
      ctx.addIssue({ code: "custom", path: ["conditionGrade"], message: "Исправный контейнер не может иметь грейд «Damaged»" });
    }
  });

export type InspectionInput = z.input<typeof inspectionSchema>;

/**
 * Акт осмотра: фиксирует грейд и тех. статус. Переходы:
 *  → IN_REPAIR: контейнер уходит в ремзону (MAINTENANCE);
 *  IN_REPAIR/DAMAGED → SOUND: ремонт закрыт, EOR списывается в затраты на ремонт, контейнер возвращается на сток.
 */
export async function inspectContainerAction(containerId: string, input: InspectionInput): Promise<ActionResult> {
  const auth = await authorize("inspection");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(inspectionSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;
  const c = await prisma.container.findUnique({ where: { id: containerId } });
  if (!c) return notFound("Контейнер");

  const now = new Date();
  const wasBroken = c.techStatus === "DAMAGED" || c.techStatus === "IN_REPAIR";
  const repairCompleted = wasBroken && data.techStatus === "SOUND";
  const repairStarted = data.techStatus === "IN_REPAIR" && c.techStatus !== "IN_REPAIR";
  const onSite = c.operationalStatus === "AVAILABLE" || c.operationalStatus === "MAINTENANCE";
  const repairCost = repairCompleted ? (c.eorAmountUsd ?? 0) : 0;

  const events: { type: string; description: string; amountUsd: number | null }[] = [
    {
      type: "INSPECTION",
      description: `Акт осмотра: грейд ${CONDITION_GRADE_LABELS[data.conditionGrade]}, тех. статус «${TECH_STATUS_LABELS[data.techStatus]}».${data.eorUsd ? ` EOR ${formatUsd(data.eorUsd)}.` : ""}${data.comment ? ` ${data.comment}` : ""}`,
      amountUsd: data.eorUsd,
    },
  ];
  if (repairStarted) events.push({ type: "REPAIR_START", description: `Передан в ремонт по EOR ${formatUsd(data.eorUsd ?? 0)}.`, amountUsd: data.eorUsd });
  if (repairCompleted) events.push({ type: "REPAIR_DONE", description: `Ремонт завершён, затраты ${formatUsd(repairCost)}. Контейнер исправен.`, amountUsd: repairCost || null });

  let operationalStatus = c.operationalStatus;
  if (repairStarted && onSite) operationalStatus = "MAINTENANCE";
  if (repairCompleted && c.operationalStatus === "MAINTENANCE") operationalStatus = "AVAILABLE";

  await prisma.container.update({
    where: { id: containerId },
    data: {
      conditionGrade: data.conditionGrade,
      techStatus: data.techStatus,
      eorAmountUsd: data.techStatus === "SOUND" ? null : data.eorUsd,
      operationalStatus,
      storageStartDate: operationalStatus === "AVAILABLE" ? (c.operationalStatus === "AVAILABLE" ? c.storageStartDate : startOfDayUtc(now)) : null,
      totalRepairCostUsd: { increment: repairCost },
      events: {
        create: events.map((e) => ({ ...e, occurredAt: now, locode: c.currentLocode, terminal: c.currentTerminal, actor: session.name })),
      },
    },
  });
  revalidatePath("/", "layout");
  return { ok: true, message: `${formatBic(c.bicCode)}: акт осмотра сохранён${repairCompleted ? ", ремонт закрыт" : repairStarted ? ", передан в ремонт" : ""}` };
}

const gateInSchema = z.object({ locode: locodeField, terminal: requiredText("терминал", 120) });

/** Gate-In на терминал (прибытие из собственного рейса / перемещение между депо). */
export async function gateInAction(containerId: string, input: z.input<typeof gateInSchema>): Promise<ActionResult> {
  const auth = await authorize("inspection");
  if (!auth.ok) return auth.result;
  const { session } = auth;
  const parsed = parseInput(gateInSchema, input);
  if (!parsed.ok) return parsed.result;
  const c = await prisma.container.findUnique({ where: { id: containerId } });
