413	// Простейший ограничитель перебора паролей (в памяти процесса; для кластера — Redis).
414	const MAX_ATTEMPTS = 5;
415	const WINDOW_MS = 5 * 60_000;
416	const attempts = new Map<string, { count: number; resetAt: number }>();
417	
418	function isRateLimited(key: string): boolean {
419	  const now = Date.now();
420	  const entry = attempts.get(key);
421	  if (!entry || entry.resetAt < now) return false;
422	  return entry.count >= MAX_ATTEMPTS;
423	}
424	
425	function registerFailure(key: string): void {
426	  const now = Date.now();
427	  // Не даём карте расти бесконечно при переборе случайных email.
428	  for (const [k, v] of attempts) if (v.resetAt < now) attempts.delete(k);
429	  const entry = attempts.get(key);
430	  attempts.set(key, entry && entry.resetAt > now ? { ...entry, count: entry.count + 1 } : { count: 1, resetAt: now + WINDOW_MS });
431	}
432	
433	/** bcrypt-хэш случайной строки (cost 10, как у пользователей) — для выравнивания времени ответа. */
434	const DUMMY_HASH = "$2b$10$HLDPiLxOdhyn89tcGRN3x./4cRxAuZfFAu9CwC9gP2YiKeVji2F1C";
435	
436	const INTERNAL_ORIGIN = "http://fms.internal";
437	
438	/**
439	 * Разрешаем редирект только на внутренние пути (защита от open redirect).
440	 * Разбираем как URL: браузер трактует "/\evil.com" как "//evil.com", поэтому префиксной проверки мало.
441	 */
442	function safeNext(next: string | undefined): string {
443	  if (!next || !next.startsWith("/") || next.includes("\\")) return "/";
444	  try {
445	    const url = new URL(next, INTERNAL_ORIGIN);
446	    if (url.origin !== INTERNAL_ORIGIN || url.pathname.startsWith("/login")) return "/";
447	    return `${url.pathname}${url.search}`;
448	  } catch {
449	    return "/";
450	  }
451	}
452	
453	export async function loginAction(_prev: LoginState, formData: FormData): Promise<LoginState> {
454	  const parsed = loginSchema.safeParse({
455	    email: formData.get("email"),
456	    password: formData.get("password"),
457	    next: formData.get("next") ?? undefined,
458	  });
459	  if (!parsed.success) {
460	    return { error: parsed.error.issues[0]?.message ?? "Проверьте данные", email: String(formData.get("email") ?? "") };
461	  }
462	
463	  const { email, password, next } = parsed.data;
464	  if (isRateLimited(email)) {
465	    return { error: "Слишком много попыток входа. Повторите через 5 минут.", email };
466	  }
467	
468	  let user;
469	  try {
470	    user = await prisma.user.findUnique({ where: { email } });
471	  } catch (error) {
472	    console.error("[action:auth]", error);
473	    return { error: "Сервис временно недоступен. Повторите попытку через минуту.", email };
474	  }
475	  // Для несуществующего email тоже считаем bcrypt — время ответа не выдаёт, есть ли такая учётная запись.
476	  const isValid = await bcrypt.compare(password, user?.passwordHash ?? DUMMY_HASH);
477	  if (!user || !isValid) {
478	    registerFailure(email);
479	    return { error: "Неверный email или пароль", email };
480	  }
481	
482	  attempts.delete(email);
483	  await createSessionCookie({ userId: user.id, email: user.email, name: user.name, role: user.role });
484	  redirect(safeNext(next));
485	}
