618	const MIN_SECRET_LENGTH = 32;
619	
620	function getSecretKey(): Uint8Array {
621	  const secret = process.env.AUTH_SECRET;
622	  if (!secret || secret.length < MIN_SECRET_LENGTH) {
623	    throw new Error(
624	      `AUTH_SECRET не задан или короче ${MIN_SECRET_LENGTH} символов. Скопируйте .env.example в .env и задайте секрет.`,
625	    );
626	  }
627	  return new TextEncoder().encode(secret);
628	}
