function buildHistory(spec: ContainerSpec, purchaseDate: Date, firstActivity: Date, lastReturn: Date | null, ctx: BuildContext): HistoryResult {
  const { rng } = ctx;
  const result: HistoryResult = { events: [], trips: [], revenueUsd: 0, repairCostUsd: 0 };
