39	/** Mulberry32 — детерминированный PRNG. */
40	function createRng(seed: number) {
41	  let a = seed;
42	  const next = () => {
43	    a = (a + 0x6d2b79f5) | 0;
44	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
45	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
46	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
47	  };
48	  return {
49	    next,
50	    int: (min: number, max: number) => Math.floor(next() * (max - min + 1)) + min,
51	    pick: <T>(list: readonly T[]): T => list[Math.floor(next() * list.length)],
52	  };
53	}
54	type Rng = ReturnType<typeof createRng>;
