96	/** Прошлые циклы: One-Way и собственные рейсы, ремонты, освидетельствования. */
97	function buildHistory(spec: ContainerSpec, purchaseDate: Date, firstActivity: Date, lastReturn: Date | null, ctx: BuildContext): HistoryResult {
98	  const { rng } = ctx;
99	  const result: HistoryResult = { events: [], trips: [], revenueUsd: 0, repairCostUsd: 0 };
100	  let position: Location = factoryOf(spec);
101	
102	  result.events.push({
103	    type: "PURCHASE",
104	    occurredAt: purchaseDate,
105	    locode: position[0],
106	    terminal: position[1],
107	    description: `Приобретен у ${spec.maker} (${spec.year} г.), ввод в парк «Экспортэксперт». Табличка КБК (CSC) установлена.`,
108	    actor: ACTORS.manager,
109	  });
110	  result.events.push({
111	    type: "GATE_IN",
112	    occurredAt: addDays(purchaseDate, 2),
113	    locode: position[0],
114	    terminal: position[1],
115	    description: "Gate-In на депо после приёмки с завода. Состояние: IICL-6 (новый).",
116	    actor: ACTORS.edi,
117	  });
118	
119	  const windowEnd = lastReturn ?? addDays(firstActivity, -10);
120	  // История сосредоточена в последних ~2 годах перед текущим состоянием — так таймлайн плотнее.
121	  const recentStart = addDays(windowEnd, -(spec.pastCycles * 75 + 30));
122	  const earliest = addDays(purchaseDate, 20);
123	  const windowStart = recentStart > earliest ? recentStart : earliest;
124	  const windowDays = Math.floor((windowEnd.getTime() - windowStart.getTime()) / 86_400_000);
125	  const cycles = Math.min(spec.pastCycles, Math.floor(windowDays / 40));
126	  const home = homeOf(spec);
127	
128	  for (let i = 0; i < cycles; i++) {
129	    const isLast = i === cycles - 1;
130	    const segment = Math.floor(windowDays / cycles);
131	    const dropoff: Location = isLast ? home : (() => {
132	      const route = rng.pick(HISTORY_ROUTES);
133	      return route[1][0] === position[0] ? route[0] : route[1];
134	    })();
135	    const isDispute = isLast && spec.key === "D1";
136	    const isOneWay = isDispute || rng.next() < 0.6;
137	    const freeDays = rng.pick([21, 30, 30, 45]);
138	    const overdue = isDispute ? 0 : rng.next() < 0.3 ? rng.int(2, 9) : 0;
139	    const tripDays = isOneWay ? Math.min(segment - 5, freeDays - rng.int(0, 6) + overdue) : Math.min(segment - 5, rng.int(18, 32));
140	
141	    const returnDate = isLast && lastReturn ? lastReturn : addDays(windowStart, segment * (i + 1) - rng.int(2, 6));
142	    const handover = addDays(returnDate, -Math.max(10, tripDays));
143	
144	    if (isOneWay) {
145	      const cp = isDispute ? COUNTERPARTIES[4] : rng.pick(COUNTERPARTIES);
146	      const booking = isDispute ? "OW-2026-0871" : `OW-${handover.getUTCFullYear()}-${String(rng.int(100, 899)).padStart(4, "0")}`;
147	      const fee = isDispute ? 0 : rng.pick([0, 0, 50, 100, 150]);
148	      const rate = rng.pick([10, 12, 15, 20]);
149	      const deadline = addDays(handover, isDispute ? 30 : freeDays);
150	      const realOverdue = Math.max(0, Math.round((returnDate.getTime() - deadline.getTime()) / 86_400_000));
151	      const detention = realOverdue * rate;
152	      result.trips.push({
153	        counterpartyName: cp.name,
154	        counterpartyInn: cp.inn,
155	        bookingRef: booking,
156	        pickupLocode: position[0],
157	        pickupTerminal: position[1],
158	        dropoffLocode: dropoff[0],
159	        dropoffTerminal: dropoff[1],
160	        handoverDate: handover,
161	        freeDays: isDispute ? 30 : freeDays,
162	        deadlineDate: deadline,
163	        actualReturnDate: returnDate,
164	        feeUsd: fee,
165	        detentionRatePerDayUsd: rate,
166	        status: isDispute ? "DISPUTE" : "COMPLETED",
167	        returnCondition: isDispute ? "DAMAGED" : "SOUND",
168	        returnEorUsd: isDispute ? spec.eor ?? null : null,
169	        notes: isDispute ? "Повреждение при сдаче: пробоина боковой стенки. Выставлена претензия на сумму EOR." : null,
170	      });
171	      result.events.push({
172	        type: "ONE_WAY_OUT",
173	        occurredAt: new Date(handover.getTime() + 10 * 3_600_000),
174	        locode: position[0],
175	        terminal: position[1],
176	        description: `Gate-Out: выдан в One-Way ${booking} контрагенту ${cp.name}. Маршрут ${locodeCity(position[0])} → ${locodeCity(dropoff[0])}, ${isDispute ? 30 : freeDays} свободных дней.`,
177	        amountUsd: fee > 0 ? fee : null,
178	        actor: ACTORS.dispatcher,
179	      });
180	      result.events.push({
181	        type: "ONE_WAY_IN",
182	        occurredAt: new Date(returnDate.getTime() + 14 * 3_600_000),
183	        locode: dropoff[0],
184	        terminal: dropoff[1],
185	        description: isDispute
186	          ? `Gate-In по One-Way ${booking}. При приёмке выявлено повреждение — открыт спор (DISPUTE), EOR $${spec.eor}.${detention > 0 ? ` Просрочка ${realOverdue} дн., детеншн $${detention}.` : ""}`
187	          : `Gate-In по One-Way ${booking}. Состояние при приёмке: исправен.${detention > 0 ? ` Просрочка ${realOverdue} дн., детеншн $${detention}.` : ""}`,
188	        amountUsd: detention > 0 ? detention : null,
189	        actor: ACTORS.edi,
190	      });
191	      result.revenueUsd += fee + detention;
192	    } else {
193	      const freight = rng.int(9, 22) * 100;
194	      result.events.push({
195	        type: "GATE_OUT",
196	        occurredAt: new Date(handover.getTime() + 9 * 3_600_000),
197	        locode: position[0],
198	        terminal: position[1],
199	        description: `Gate-Out: собственный гружёный рейс ${locodeCity(position[0])} → ${locodeCity(dropoff[0])}.`,
200	        actor: ACTORS.dispatcher,
201	      });
202	      result.events.push({
203	        type: "GATE_IN",
204	        occurredAt: new Date(returnDate.getTime() + 16 * 3_600_000),
205	        locode: dropoff[0],
206	        terminal: dropoff[1],
207	        description: `Gate-In после выгрузки. Маржа рейса, отнесённая на единицу: $${freight}.`,
208	        amountUsd: freight,
209	        actor: ACTORS.edi,
210	      });
211	      result.revenueUsd += freight;
212	    }
213	
214	    // Периодический осмотр и мелкий ремонт после рейса (не для последнего цикла перед текущим состоянием).
215	    if (!isLast && rng.next() < 0.35) {
216	      const cost = rng.int(12, 48) * 10;
217	      const repairDay = addDays(returnDate, 2);
218	      result.events.push({
219	        type: "REPAIR_START",
220	        occurredAt: new Date(repairDay.getTime() + 11 * 3_600_000),
221	        locode: dropoff[0],
222	        terminal: dropoff[1],
223	        description: `Передан в ремонт по EOR $${cost}: ${rng.pick(["правка гофры боковой стенки", "замена уплотнителей дверей", "ремонт напольного покрытия", "правка нижней поперечины"])}.`,
224	        amountUsd: cost,
225	        actor: ACTORS.manager,
226	      });
227	      result.events.push({
228	        type: "REPAIR_DONE",
229	        occurredAt: new Date(addDays(repairDay, 3).getTime() + 15 * 3_600_000),
230	        locode: dropoff[0],
231	        terminal: dropoff[1],
232	        description: `Ремонт завершён, фактическая стоимость $${cost}. Грейд восстановлен до Cargo Worthy.`,
233	        amountUsd: cost,
234	        actor: ACTORS.manager,
235	      });
236	      result.repairCostUsd += cost;
237	    }
238	    position = dropoff;
239	  }
240	  return result;
241	}
