249	function buildContainer(spec: ContainerSpec, ctx: BuildContext): ContainerBuild {
250	  const { rng, today, at } = ctx;
251	  const stateStart = addDays(today, -spec.sinceDays);
252	  const lease = LEASES.find((l) => l.containerKeys.includes(spec.key));
253	  const firstActivity = lease ? addDays(today, -lease.startDaysAgo) : stateStart;
254	
255	  let purchaseDate = new Date(Date.UTC(spec.year, rng.int(0, 10), rng.int(1, 28)));
256	  if (purchaseDate.getTime() > addDays(firstActivity, -45).getTime()) purchaseDate = addDays(firstActivity, -45);
257	
258	  // Для контейнеров, прибывших на текущий сток/ремонт после рейса, последний цикл заканчивается Gate-In'ом сюда.
259	  const arrivesFromTrip = (spec.op === "AVAILABLE" || spec.op === "MAINTENANCE") && !lease && spec.pastCycles > 0;
260	  const lastReturn = arrivesFromTrip ? addDays(stateStart, spec.op === "MAINTENANCE" ? -2 : 0) : null;
261	  const history = buildHistory(spec, purchaseDate, firstActivity, lastReturn, ctx);
262	  const events = [...history.events];
263	  const [locode, terminal] = homeOf(spec);
264	  const cscExpiry = addDays(today, spec.cscDays);
265	  let revenue = history.revenueUsd;
266	
267	  const lastAcep = addMonths(cscExpiry, -30);
268	  if (lastAcep > addDays(purchaseDate, 365) && lastAcep < today) {
269	    events.push({
270	      type: "CSC_RENEWAL",
271	      occurredAt: new Date(lastAcep.getTime() + 12 * 3_600_000),
272	      locode,
273	      terminal,
274	      description: `Освидетельствование по программе ACEP пройдено. Табличка КБК (CSC) действительна до ${formatDate(cscExpiry)}.`,
275	      actor: ACTORS.manager,
276	    });
277	  }
278	
279	  // Текущее состояние
280	  switch (spec.op) {
281	    case "ONE_WAY": {
282	      const trip = ACTIVE_TRIPS.find((t) => t.containerKey === spec.key);
283	      if (trip) {
284	        events.push(
285	          { type: "INSPECTION", occurredAt: at(-spec.sinceDays - 1, 15), locode, terminal, description: "Предрейсовый осмотр (EIR): Cargo Worthy, пломбировочные устройства исправны.", actor: `Инспектор ${terminal}` },
286	          { type: "ONE_WAY_OUT", occurredAt: at(-spec.sinceDays, 10), locode, terminal, description: `Gate-Out: выдан в One-Way ${trip.bookingRef} контрагенту ${trip.counterparty}. Возврат: ${locodeCity(trip.dropoff[0])}, ${trip.dropoff[1]}; ${trip.freeDays} свободных дней.`, amountUsd: trip.feeUsd || null, actor: ACTORS.dispatcher },
287	        );
288	        revenue += trip.feeUsd;
289	      }
290	      break;
291	    }
292	    case "LONG_TERM_LEASE":
293	    case "AVAILABLE":
294	    case "MAINTENANCE":
295	    case "IN_TRANSIT":
296	      break;
297	  }
298	
299	  if (lease) {
300	    const onHire = addDays(today, -lease.startDaysAgo);
301	    const offHire = lease.offHireDaysAgo !== undefined ? addDays(today, -lease.offHireDaysAgo) : null;
302	    events.push(
303	      { type: "INSPECTION", occurredAt: new Date(addDays(onHire, -1).getTime() + 14 * 3_600_000), locode, terminal, description: `On-Hire Survey по договору ${lease.contractNumber}: Cargo Worthy, акт подписан сторонами.`, actor: `Инспектор ${terminal}` },
304	      { type: "LEASE_ON_HIRE", occurredAt: new Date(onHire.getTime() + 11 * 3_600_000), locode, terminal, description: `On-Hire: передан в долгосрочную аренду ${lease.lessee} по договору ${lease.contractNumber}, Per Diem $${lease.dailyRate.toFixed(2)}.`, actor: ACTORS.manager },
305	    );
306	    if (offHire) {
307	      // Как в offHireAction: аренда попадает в выручку при Off-Hire. Для единиц на руках её начислит будущий Off-Hire.
308	      revenue += rentalDaysInRange({ onHireDate: onHire, offHireDate: offHire }, onHire, offHire) * lease.dailyRate;
309	      events.push(
310	        { type: "LEASE_OFF_HIRE", occurredAt: new Date(offHire.getTime() + 13 * 3_600_000), locode, terminal, description: `Off-Hire: возвращен из аренды по договору ${lease.contractNumber}. Off-Hire Survey подписан, повреждений нет.`, actor: ACTORS.manager },
311	        { type: "GATE_IN", occurredAt: new Date(offHire.getTime() + 15 * 3_600_000), locode, terminal, description: "Gate-In на сток после возврата из аренды. Ожидает выдачи.", actor: ACTORS.edi },
312	      );
313	    }
314	  }
315	
316	  if (spec.op === "AVAILABLE" && !lease && spec.pastCycles === 0) {
317	    events.push({ type: "GATE_IN", occurredAt: at(-spec.sinceDays, 12), locode, terminal, description: "Gate-In на сток (доставлен с завода собственным рейсом).", actor: ACTORS.edi });
318	  }
319	  if (spec.key === "D1") {
320	    events.push({ type: "INSPECTION", occurredAt: at(-spec.sinceDays + 1, 11), locode, terminal, description: `Акт осмотра: ${spec.notes} EOR согласуется: $${spec.eor}.`, amountUsd: spec.eor, actor: `Инспектор ${terminal}` });
321	  }
322	  if (spec.key === "D2") {
323	    events.push(
324	      { type: "INSPECTION", occurredAt: at(-spec.sinceDays - 1, 10), locode, terminal, description: `Акт осмотра: повреждение пола и дверного проёма. Оценка ремонта (EOR) $${spec.eor}.`, amountUsd: spec.eor, actor: `Инспектор ${terminal}` },
325	      { type: "REPAIR_START", occurredAt: at(-spec.sinceDays, 9), locode, terminal, description: `Передан в ремонтную зону депо. EOR $${spec.eor} согласован, срок ремонта — 14 дней.`, amountUsd: spec.eor, actor: ACTORS.manager },
326	    );
327	  }
328	  if (spec.key === "H1") {
329	    events.push({ type: "STATUS_CHANGE", occurredAt: at(-spec.sinceDays + 1, 16), locode, terminal, description: "Тех. статус → HOLD. Блокировка ФТС: досмотр по последней поставке. Выдача запрещена.", actor: ACTORS.manager });
330	  }
331	  if (spec.op === "IN_TRANSIT") {
332	    events.push({ type: "GATE_OUT", occurredAt: at(-spec.sinceDays, 8), locode, terminal: homeOf(spec)[1], description: `Gate-Out: собственный гружёный рейс. ${spec.terminal.replace("В пути: ", "")}.`, actor: ACTORS.dispatcher });
333	  }
334	
335	  const weights = DEFAULT_WEIGHTS[spec.size];
336	  const tare = weights.tare + rng.int(-4, 6) * 10;
337	  const price = BASE_PRICE[spec.size] + rng.int(-6, 9) * 50;
338	  const onStock = spec.op === "AVAILABLE";
339	  const terminalLabel =
340	    spec.op === "ONE_WAY" ? `Выдан: ${ACTIVE_TRIPS.find((t) => t.containerKey === spec.key)?.counterparty ?? "контрагент"}`
341	    : spec.op === "LONG_TERM_LEASE" ? `В аренде: ${lease?.lessee ?? "арендатор"}`
342	    : spec.terminal;
343	
344	  return {
345	    data: {
346	      bicCode: buildBic(spec.prefix, spec.serial),
347	      sizeType: spec.size,
348	      isoCode: DEFAULT_ISO_CODE[spec.size],
349	      manufactureYear: spec.year,
350	      colorRal: RAL_BY_PREFIX[spec.prefix] ?? "RAL 5013",
351	      manufacturer: spec.maker,
352	      tareWeightKg: tare,
353	      maxGrossWeightKg: weights.gross,
354	      maxPayloadKg: weights.gross - tare,
355	      conditionGrade: spec.grade,
356	      techStatus: spec.tech,
357	      cscPlateExpiry: cscExpiry,
358	      eorAmountUsd: spec.eor ?? null,
359	      operationalStatus: spec.op,
360	      currentLocode: spec.locode,
361	      currentTerminal: terminalLabel,
362	      storageStartDate: onStock ? stateStart : null,
363	      storageRatePerDayUsd: onStock ? spec.storageRate ?? null : null,
364	      purchaseDate,
365	      purchasePriceUsd: price,
366	      currentBookValueUsd: bookValue(price, purchaseDate, today),
367	      totalRevenueUsd: Math.round(revenue * 100) / 100,
368	      totalRepairCostUsd: history.repairCostUsd,
369	      notes: spec.notes ?? null,
370	    },
371	    events,
372	    trips: history.trips,
373	  };
374	}
