391	export async function seedDatabase(prisma: PrismaClient, now: Date = new Date()): Promise<SeedSummary> {
392	  const today = startOfDayUtc(now);
393	  const ctx: BuildContext = {
394	    rng: createRng(6346),
395	    today,
396	    at: (dayOffset, hour = 12) => new Date(addDays(today, dayOffset).getTime() + hour * 3_600_000),
397	  };
398	  const builds = CONTAINERS.map((spec) => ({ spec, build: buildContainer(spec, ctx) }));
399	
400	  // Все строки собираются в памяти с заранее выданными id и пишутся пакетно (createMany):
401	  // ~12 запросов вместо ~120 — критично для облачной БД и serverless-функции «Сбросить демо-данные».
402	  const idByKey = new Map<string, string>(builds.map(({ spec }) => [spec.key, randomUUID()]));
403	  const idOf = (key: string, context: string): string => {
404	    const id = idByKey.get(key);
405	    if (!id) throw new Error(`Не найден контейнер ${key} (${context})`);
406	    return id;
407	  };
408	
409	  const containers = builds.map(({ spec, build }) => ({ id: idOf(spec.key, "контейнер"), ...build.data }));
410	  const events = builds.flatMap(({ spec, build }) =>
411	    build.events
412	      .filter((e) => new Date(e.occurredAt).getTime() <= now.getTime())
413	      .map((e) => ({ ...e, containerId: idOf(spec.key, "событие") })),
414	  );
415	  const historyTrips = builds.flatMap(({ spec, build }) => build.trips.map((t) => ({ ...t, containerId: idOf(spec.key, "история One-Way") })));
416	  const activeTrips: Prisma.OneWayTripCreateManyInput[] = ACTIVE_TRIPS.map((trip) => {
417	    const spec = CONTAINERS.find((c) => c.key === trip.containerKey);
418	    if (!spec) throw new Error(`Не найден контейнер ${trip.containerKey} для One-Way`);
419	    const handover = addDays(today, -spec.sinceDays);
420	    return {
421	      containerId: idOf(trip.containerKey, "One-Way"),
422	      counterpartyName: trip.counterparty,
423	      counterpartyInn: trip.inn,
424	      counterpartyContact: trip.contact,
425	      bookingRef: trip.bookingRef,
426	      pickupLocode: spec.locode,
427	      pickupTerminal: spec.terminal,
428	      dropoffLocode: trip.dropoff[0],
429	      dropoffTerminal: trip.dropoff[1],
430	      handoverDate: handover,
431	      freeDays: trip.freeDays,
432	      deadlineDate: addDays(handover, trip.freeDays),
433	      feeUsd: trip.feeUsd,
434	      detentionRatePerDayUsd: trip.detentionRate,
435	      status: "ACTIVE",
436	    };
437	  });
438	
439	  const leaseContracts: Prisma.LeaseContractCreateManyInput[] = [];
440	  const leaseItems: Prisma.LeaseItemCreateManyInput[] = [];
441	  for (const lease of LEASES) {
442	    const leaseId = randomUUID();
443	    const startDate = addDays(today, -lease.startDaysAgo);
444	    const offHire = lease.offHireDaysAgo !== undefined ? addDays(today, -lease.offHireDaysAgo) : null;
445	    leaseContracts.push({
446	      id: leaseId,
447	      contractNumber: lease.contractNumber,
448	      lesseeName: lease.lessee,
449	      lesseeInn: lease.inn,
450	      contactPerson: lease.contactPerson,
451	      contactPhone: lease.phone,
452	      contactEmail: lease.email,
453	      startDate,
454	      endDate: addDays(today, lease.endInDays),
455	      autoRenewal: lease.autoRenewal,
456	      dailyRateUsd: lease.dailyRate,
457	      depositUsd: lease.deposit,
458	      paymentStatus: lease.paymentStatus,
459	      allowedReturnLocodes: lease.allowedReturn.join(","),
460	      onHireSurvey: "SIGNED",
461	      offHireSurvey: lease.status === "COMPLETED" ? "SIGNED" : lease.endInDays <= 14 ? "PENDING" : "NOT_STARTED",
462	      status: lease.status,
463	      notes: lease.notes ?? null,
464	    });
465	    for (const key of lease.containerKeys) {
466	      leaseItems.push({
467	        leaseId,
468	        containerId: idOf(key, `договор ${lease.contractNumber}`),
469	        onHireDate: startDate,
470	        offHireDate: offHire,
471	        returnLocode: offHire ? lease.allowedReturn[0] : null,
472	      });
473	    }
474	  }
475	
476	  // Хэши паролей считаем до транзакции, чтобы не держать её открытой во время bcrypt.
477	  const users = await Promise.all(DEMO_USERS.map(async (u) => ({ ...u, passwordHash: await bcrypt.hash(u.password, 10) })));
478	
479	  return prisma.$transaction(
480	    async (tx) => {
481	      await clearDomainData(tx);
482	      for (const user of users) {
483	        await tx.user.upsert({
484	          where: { email: user.email },
485	          update: { name: user.name, role: user.role, passwordHash: user.passwordHash },
486	          create: { email: user.email, name: user.name, role: user.role, passwordHash: user.passwordHash },
487	        });
488	      }
489	      await tx.container.createMany({ data: containers });
490	      await tx.containerEvent.createMany({ data: events });
491	      await tx.oneWayTrip.createMany({ data: [...historyTrips, ...activeTrips] });
492	      await tx.leaseContract.createMany({ data: leaseContracts });
493	      await tx.leaseItem.createMany({ data: leaseItems });
494	
495	      return { containers: containers.length, events: events.length, oneWayTrips: historyTrips.length + activeTrips.length, leases: leaseContracts.length };
496	    },
497	    { timeout: 60_000, maxWait: 15_000 },
498	  );
499	}
