  const hotTrips = trips
    .filter((t) => t.timing.status === "OVERDUE" || t.timing.isHot)
    .sort((a, b) => b.timing.overdueDays - a.timing.overdueDays || (a.timing.daysLeft ?? 0) - (b.timing.daysLeft ?? 0));
