import { mkdtemp, readdir, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterAll, describe, expect, test } from "vitest";
import { contentDisposition, detectMimeType, MAX_ATTACHMENT_BYTES, validateUpload } from "./validation";
import { createLocalDiskStorage, isValidStorageKey, newStorageKey } from "./storage";

const PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 0x0d]);
const JPEG = Buffer.from([0xff, 0xd8, 0xff, 0xe0, 0, 0x10, 0x4a, 0x46]);
const PDF = Buffer.from("%PDF-1.7\n%âãÏÓ\n", "latin1");
const HTML = Buffer.from("<html><script>alert(1)</script></html>");

describe("file type is detected by signature, not by extension (2.6)", () => {
  test("PNG, JPEG and PDF are recognised", () => {
    expect(detectMimeType(PNG)).toBe("image/png");
    expect(detectMimeType(JPEG)).toBe("image/jpeg");
    expect(detectMimeType(PDF)).toBe("application/pdf");
  });

  test("an HTML file renamed to .png is rejected", () => {
    expect(detectMimeType(HTML)).toBeNull();
    expect(validateUpload({ name: "eir.png", size: HTML.length }, HTML)).toEqual({ ok: false, error: "Допустимы только PNG, JPEG и PDF (тип определяется по содержимому файла)" });
  });

  test("a PNG named .pdf is stored as PNG", () => {
    expect(validateUpload({ name: "act.pdf", size: PNG.length }, PNG)).toMatchObject({ ok: true, mimeType: "image/png" });
  });

  test("files over 5 MB and empty files are rejected", () => {
    const big = Buffer.concat([PNG, Buffer.alloc(MAX_ATTACHMENT_BYTES)]);
    expect(validateUpload({ name: "big.png", size: big.length }, big)).toMatchObject({ ok: false });
    expect(validateUpload({ name: "e.png", size: 0 }, Buffer.alloc(0))).toMatchObject({ ok: false });
    expect(MAX_ATTACHMENT_BYTES).toBe(5 * 1024 * 1024);
  });

  test("the declared size must match the bytes actually received", () => {
    expect(validateUpload({ name: "x.png", size: 3 }, PNG)).toMatchObject({ ok: false });
  });

  test("the file name is sanitised for storage and download headers", () => {
    const r = validateUpload({ name: "../../etc/Акт осмотра\r\n.png", size: PNG.length }, PNG);
    expect(r).toMatchObject({ ok: true, fileName: "Акт осмотра.png" });
    expect(contentDisposition("Акт №1.pdf", "attachment")).toBe(`attachment; filename="1.pdf"; filename*=UTF-8''%D0%90%D0%BA%D1%82%20%E2%84%961.pdf`);
  });
});

describe("storage abstraction: local disk driver", () => {
  const dirs: string[] = [];
  afterAll(async () => Promise.all(dirs.map((d) => rm(d, { recursive: true, force: true }))));

  test("put / get / delete round-trip outside the public folder", async () => {
    const dir = await mkdtemp(path.join(tmpdir(), "fms-att-"));
    dirs.push(dir);
    const storage = createLocalDiskStorage(dir);
    const key = newStorageKey();
    await storage.put(key, PDF);
    expect(await storage.get(key)).toEqual(PDF);
    expect(await readdir(dir)).toHaveLength(1);
    await storage.delete(key);
    expect(await storage.get(key)).toBeNull();
  });

  test("keys are generated, never taken from user input (no path traversal)", async () => {
    expect(isValidStorageKey(newStorageKey())).toBe(true);
    expect(isValidStorageKey("../../etc/passwd")).toBe(false);
    const storage = createLocalDiskStorage(path.join(tmpdir(), "fms-att-guard"));
    await expect(storage.get("../secret")).rejects.toThrow(/ключ/);
  });
});

/** Проверка загружаемых вложений (2.6): размер ≤ 5 МБ, тип — только по сигнатуре содержимого. */

export const MAX_ATTACHMENT_BYTES = 5 * 1024 * 1024;

export const ATTACHMENT_MIME_TYPES = ["image/png", "image/jpeg", "application/pdf"] as const;
export type AttachmentMimeType = (typeof ATTACHMENT_MIME_TYPES)[number];

const SIGNATURES: { mime: AttachmentMimeType; bytes: number[] }[] = [
  { mime: "image/png", bytes: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] },
  { mime: "image/jpeg", bytes: [0xff, 0xd8, 0xff] },
  { mime: "application/pdf", bytes: [0x25, 0x50, 0x44, 0x46, 0x2d] }, // %PDF-
];

export function detectMimeType(data: Uint8Array): AttachmentMimeType | null {
  const match = SIGNATURES.find((s) => s.bytes.every((b, i) => data[i] === b));
  return match?.mime ?? null;
}

export type UploadCheck = { ok: true; mimeType: AttachmentMimeType; fileName: string } | { ok: false; error: string };

/** Имя файла: без пути и управляющих символов, не длиннее 120 символов. */
export function sanitizeFileName(name: string): string {
  const base = name.split(/[\\/]/).pop() ?? "";
  const clean = base.replace(/[\u0000-\u001f\u007f"<>|:*?]/g, "").replace(/^\.+/, "").trim();
  return (clean || "файл").slice(0, 120);
}

export function validateUpload(file: { name: string; size: number }, data: Uint8Array): UploadCheck {
  if (data.length === 0 || file.size === 0) return { ok: false, error: "Файл пустой" };
  if (data.length > MAX_ATTACHMENT_BYTES || file.size > MAX_ATTACHMENT_BYTES) return { ok: false, error: "Файл больше 5 МБ" };
  if (data.length !== file.size) return { ok: false, error: "Файл передан не полностью — повторите загрузку" };
  const mimeType = detectMimeType(data);
  if (!mimeType) return { ok: false, error: "Допустимы только PNG, JPEG и PDF (тип определяется по содержимому файла)" };
  return { ok: true, mimeType, fileName: sanitizeFileName(file.name) };
}

/** Content-Disposition с ASCII-запасным именем и UTF-8 по RFC 5987. */
export function contentDisposition(fileName: string, type: "inline" | "attachment"): string {
  const ascii = fileName.replace(/[^\x20-\x7e]/g, "").replace(/["\\]/g, "").replace(/\s+/g, " ").trim() || "file";
  const encoded = encodeURIComponent(fileName).replace(/['()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
  return `${type}; filename="${ascii}"; filename*=UTF-8''${encoded}`;
}

/**
 * Хранилище вложений — абстракция (2.6). Драйверы:
 *  local — каталог на диске вне public (ATTACHMENTS_DIR, по умолчанию .data/attachments) — для разработки;
 *  db    — таблица AttachmentBlob в PostgreSQL — для прода без объектного хранилища (Render + Neon):
 *          файлы ≤ 5 МБ, переживают передеплой, бэкапятся вместе с БД.
 * S3-совместимый драйвер и Vercel Blob (private) подключаются реализацией того же интерфейса — см. docs/ARCHITECTURE.md.
 */
import { randomUUID } from "node:crypto";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

export interface AttachmentStorage {
  readonly driver: string;
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

const KEY_PATTERN = /^att_[0-9a-f]{32}$/;

export function newStorageKey(): string {
  return `att_${randomUUID().replace(/-/g, "")}`;
}

export function isValidStorageKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}

function assertKey(key: string): void {
  if (!isValidStorageKey(key)) throw new Error("Недопустимый ключ вложения");
}

export function createLocalDiskStorage(dir: string): AttachmentStorage {
  const root = path.resolve(dir);
  const fileOf = (key: string) => {
    assertKey(key);
    return path.join(root, key);
  };
  return {
    driver: "local",
    async put(key, data) {
      const file = fileOf(key);
      await mkdir(root, { recursive: true });
      await writeFile(file, data, { flag: "wx" });
    },
    async get(key) {
      try {
        return await readFile(fileOf(key));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },
    async delete(key) {
      await rm(fileOf(key), { force: true });
    },
  };
}

/** Минимальный контракт Prisma для драйвера «db» — не тянем сюда весь клиент. */
export interface BlobTable {
  attachmentBlob: {
    create(args: { data: { storageKey: string; data: Uint8Array<ArrayBuffer> } }): Promise<unknown>;
    findUnique(args: { where: { storageKey: string } }): Promise<{ data: Uint8Array } | null>;
    deleteMany(args: { where: { storageKey: string } }): Promise<unknown>;
  };
}

export function createDatabaseStorage(db: BlobTable): AttachmentStorage {
  return {
    driver: "db",
    async put(key, data) {
      assertKey(key);
      await db.attachmentBlob.create({ data: { storageKey: key, data: new Uint8Array(data) } });
    },
    async get(key) {
      assertKey(key);
      const row = await db.attachmentBlob.findUnique({ where: { storageKey: key } });
      return row ? Buffer.from(row.data) : null;
    },
    async delete(key) {
      assertKey(key);
      await db.attachmentBlob.deleteMany({ where: { storageKey: key } });
    },
  };
}

export type StorageDriver = "local" | "db";

/** ATTACHMENTS_DRIVER=local|db; по умолчанию db в production и local в разработке. */
export function resolveStorageDriver(env: Record<string, string | undefined> = process.env): StorageDriver {
  const value = env.ATTACHMENTS_DRIVER;
  if (value === "local" || value === "db") return value;
  return env.NODE_ENV === "production" ? "db" : "local";
}

export function attachmentsDir(env: Record<string, string | undefined> = process.env): string {
  return env.ATTACHMENTS_DIR || path.join(process.cwd(), ".data", "attachments");
}

