import { prisma } from "@/lib/prisma";
import { audit } from "@/lib/audit";
import { LOGIN_LIMITS, checkLoginAllowed, clearLoginFailures, registerLoginFailure } from "@/lib/auth/rate-limit";
import { createUser, resetDomain } from "../../test/fixtures";

beforeEach(() => resetDomain(prisma));
afterAll(() => prisma.$disconnect());

describe("3.7 AuditLog is written in the same transaction as the mutation", () => {
  test("committed together", async () => {
    const user = await createUser(prisma, "MANAGER");
    await prisma.$transaction(async (tx) => {
      await audit(tx, { actor: user, action: "CONTAINER_UPDATE", entityType: "Container", entityId: "c1", summary: "Карточка обновлена" });
    });
    const rows = await prisma.auditLog.findMany();
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({ userId: user.id, actorName: user.name, action: "CONTAINER_UPDATE", entityId: "c1" });
  });

  test("rolled back together when the operation fails", async () => {
    const user = await createUser(prisma, "MANAGER");
    await expect(
      prisma.$transaction(async (tx) => {
        await audit(tx, { actor: user, action: "ONE_WAY_ISSUE", entityType: "OneWayTrip", entityId: "t1", summary: "Выдача" });
        throw new Error("операция не прошла");
      }),
    ).rejects.toThrow("операция не прошла");
    expect(await prisma.auditLog.count()).toBe(0);
  });
});

describe("3.2 login rate limit in PostgreSQL (D-09)", () => {
  const T0 = new Date("2026-10-27T09:00:00.000Z");

  test(`${LOGIN_LIMITS.perIpEmail.max} failures from one IP lock that IP + email only`, async () => {
    for (let i = 0; i < LOGIN_LIMITS.perIpEmail.max; i++) await registerLoginFailure("10.0.0.1", "admin@fms.ru", T0);

    expect(await checkLoginAllowed("10.0.0.1", "admin@fms.ru", T0)).toMatchObject({ allowed: false });
    // Владелец с другого IP с верным паролем не заперт.
    expect(await checkLoginAllowed("192.168.5.7", "admin@fms.ru", T0)).toEqual({ allowed: true });
    // Атакующий IP может войти под другим email (лимит на IP — выше).
    expect(await checkLoginAllowed("10.0.0.1", "manager@fms.ru", T0)).toEqual({ allowed: true });
  });

  test("the lock expires after the window", async () => {
    for (let i = 0; i < LOGIN_LIMITS.perIpEmail.max; i++) await registerLoginFailure("10.0.0.2", "a@fms.ru", T0);
    const later = new Date(T0.getTime() + LOGIN_LIMITS.perIpEmail.windowMs + 1000);
    expect(await checkLoginAllowed("10.0.0.2", "a@fms.ru", later)).toEqual({ allowed: true });
    await registerLoginFailure("10.0.0.2", "a@fms.ru", later);
    const row = await prisma.loginAttempt.findUniqueOrThrow({ where: { key: "10.0.0.2|a@fms.ru" } });
    expect(row.count).toBe(1); // окно началось заново
  });

  test("password spraying from one IP across many emails hits the per-IP limit", async () => {
    for (let i = 0; i < LOGIN_LIMITS.perIp.max; i++) await registerLoginFailure("10.0.0.3", `user${i}@fms.ru`, T0);
    expect(await checkLoginAllowed("10.0.0.3", "fresh@fms.ru", T0)).toMatchObject({ allowed: false });
  });

  test("parallel failures are counted atomically (shared by all app instances)", async () => {
    await Promise.all(Array.from({ length: 20 }, () => registerLoginFailure("10.0.0.4", "b@fms.ru", T0)));
    const row = await prisma.loginAttempt.findUniqueOrThrow({ where: { key: "10.0.0.4|b@fms.ru" } });
    expect(row.count).toBe(20);
  });

  test("a successful login clears the IP + email counter", async () => {
    await registerLoginFailure("10.0.0.5", "c@fms.ru", T0);
    await clearLoginFailures("10.0.0.5", "c@fms.ru");
    expect(await prisma.loginAttempt.findUnique({ where: { key: "10.0.0.5|c@fms.ru" } })).toBeNull();
  });
});

/**
 * Аудит-журнал (3.7): кто (userId) и когда выполнил мутацию. Вызывается с клиентом транзакции операции —
 * запись фиксируется или откатывается вместе с ней.
 */
import type { Prisma } from "@prisma/client";

export type AuditAction =
  | "AUTH_LOGIN"
  | "AUTH_LOGOUT"
  | "USER_PASSWORD_CHANGE"
  | "USER_ROLE_CHANGE"
  | "USER_CREATE"
  | "CONTAINER_CREATE"
  | "CONTAINER_UPDATE"
  | "CONTAINER_WRITE_OFF"
  | "CONTAINER_EVENT_ADD"
  | "ATTACHMENT_UPLOAD"
  | "INSPECTION"
  | "GATE_IN"
  | "GATE_OUT"
  | "CSC_RENEWAL"
  | "ONE_WAY_ISSUE"
  | "ONE_WAY_RETURN"
  | "ONE_WAY_DISPUTE_RESOLVE"
  | "LEASE_CREATE"
  | "LEASE_ACTIVATE"
  | "LEASE_EXTEND"
  | "LEASE_OFF_HIRE"
  | "LEASE_PAYMENT_STATUS"
  | "DEMO_RESET";

export const AUDIT_ACTION_LABELS: Record<AuditAction, string> = {
  AUTH_LOGIN: "Вход",
  AUTH_LOGOUT: "Выход",
  USER_PASSWORD_CHANGE: "Смена пароля",
  USER_ROLE_CHANGE: "Смена роли",
  USER_CREATE: "Новый пользователь",
  CONTAINER_CREATE: "Контейнер добавлен",
  CONTAINER_UPDATE: "Карточка изменена",
  CONTAINER_WRITE_OFF: "Списание",
  CONTAINER_EVENT_ADD: "Запись в журнал",
  ATTACHMENT_UPLOAD: "Вложение",
  INSPECTION: "Акт осмотра",
  GATE_IN: "Gate-In",
  GATE_OUT: "Gate-Out",
  CSC_RENEWAL: "Продление КБК",
  ONE_WAY_ISSUE: "Выдача One-Way",
  ONE_WAY_RETURN: "Возврат One-Way",
  ONE_WAY_DISPUTE_RESOLVE: "Претензия закрыта",
  LEASE_CREATE: "Договор аренды",
  LEASE_ACTIVATE: "On-Hire по договору",
  LEASE_EXTEND: "Продление аренды",
  LEASE_OFF_HIRE: "Off-Hire",
  LEASE_PAYMENT_STATUS: "Статус оплаты",
  DEMO_RESET: "Сброс демо-данных",
};

export interface AuditEntry {
  /** null — системное действие (ленивая активация договора, bootstrap). */
  actor: { id: string; name: string } | null;
  action: AuditAction;
  entityType: string;
  entityId?: string | null;
  summary: string;
  details?: Prisma.InputJsonValue;
}

export interface AuditWriter {
  auditLog: { create(args: { data: Prisma.AuditLogUncheckedCreateInput }): Promise<unknown> };
}

export async function audit(tx: AuditWriter, entry: AuditEntry): Promise<void> {
  await tx.auditLog.create({
    data: {
      userId: entry.actor?.id ?? null,
      actorName: entry.actor?.name ?? "Система FMS",
      action: entry.action,
      entityType: entry.entityType,
      entityId: entry.entityId ?? null,
      summary: entry.summary.slice(0, 1000),
      details: entry.details,
    },
  });
}

import "server-only";
import { prisma } from "@/lib/prisma";

/**
 * Ограничитель перебора паролей (D-09) в PostgreSQL — общий для всех инстансов приложения.
 * Ключи: «ip|email» (5 ошибок за 15 мин) и «ip» (30 ошибок за 15 мин, против перебора по многим email).
 * Владелец учётной записи с другого IP не блокируется: ключ включает IP.
 */
export const LOGIN_LIMITS = {
  perIpEmail: { max: 5, windowMs: 15 * 60_000 },
  perIp: { max: 30, windowMs: 15 * 60_000 },
} as const;

const keys = (ip: string, email: string) => ({ ipEmail: `${ip}|${email}`, ip: `${ip}|*` });

export type LoginCheck = { allowed: true } | { allowed: false; retryAfterSec: number };

export async function checkLoginAllowed(ip: string, email: string, now: Date = new Date()): Promise<LoginCheck> {
  const k = keys(ip, email);
  const rows = await prisma.loginAttempt.findMany({ where: { key: { in: [k.ipEmail, k.ip] }, resetAt: { gt: now } } });
  const blocked = rows.filter((r) => r.count >= (r.key === k.ip ? LOGIN_LIMITS.perIp.max : LOGIN_LIMITS.perIpEmail.max));
  if (blocked.length === 0) return { allowed: true };
  const until = Math.max(...blocked.map((r) => r.resetAt.getTime()));
  return { allowed: false, retryAfterSec: Math.ceil((until - now.getTime()) / 1000) };
}

/** Атомарный upsert: окно начинается заново, если прошлое истекло. */
async function bump(key: string, windowMs: number, now: Date): Promise<void> {
  const resetAt = new Date(now.getTime() + windowMs);
  await prisma.$executeRaw`
    INSERT INTO "LoginAttempt" ("key", "count", "resetAt") VALUES (${key}, 1, ${resetAt})
    ON CONFLICT ("key") DO UPDATE SET
      "count" = CASE WHEN "LoginAttempt"."resetAt" <= ${now} THEN 1 ELSE "LoginAttempt"."count" + 1 END,
      "resetAt" = CASE WHEN "LoginAttempt"."resetAt" <= ${now} THEN ${resetAt} ELSE "LoginAttempt"."resetAt" END`;
}

export async function registerLoginFailure(ip: string, email: string, now: Date = new Date()): Promise<void> {
  const k = keys(ip, email);
  await bump(k.ipEmail, LOGIN_LIMITS.perIpEmail.windowMs, now);
  await bump(k.ip, LOGIN_LIMITS.perIp.windowMs, now);
  // Уборка истёкших записей, чтобы таблица не росла от перебора случайных email.
  await prisma.loginAttempt.deleteMany({ where: { resetAt: { lt: new Date(now.getTime() - 24 * 3_600_000) } } });
}

export async function clearLoginFailures(ip: string, email: string): Promise<void> {
  await prisma.loginAttempt.deleteMany({ where: { key: keys(ip, email).ipEmail } });
}

/**
 * IP клиента за обратным прокси. Берём адрес, добавленный ближайшим доверенным прокси
 * (TRUSTED_PROXY_HOPS, по умолчанию 1 — балансировщик Render/Vercel): левые элементы X-Forwarded-For клиент может подделать.
 */
export function clientIp(headers: Pick<Headers, "get">, trustedHops: number = Number(process.env.TRUSTED_PROXY_HOPS ?? "1")): string {
  const chain = (headers.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  const hops = Number.isInteger(trustedHops) && trustedHops > 0 ? trustedHops : 1;
  return chain[chain.length - hops] ?? chain[0] ?? headers.get("x-real-ip") ?? "unknown";
}

