"use client";

import { useState } from "react";
import { KeyRound } from "lucide-react";
import { changePasswordAction } from "@/actions/auth";
import { Button } from "@/components/ui/button";
import { Field, Input } from "@/components/ui/primitives";
import { useServerAction } from "@/components/use-server-action";

const EMPTY = { currentPassword: "", newPassword: "", confirmPassword: "" };

export function ChangePasswordForm() {
  const [values, setValues] = useState(EMPTY);
  const { run, isPending, fieldErrors } = useServerAction();
  const set = (key: keyof typeof values, value: string) => setValues((prev) => ({ ...prev, [key]: value }));

  return (
    <form
      className="max-w-md space-y-4"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => changePasswordAction(values), () => setValues(EMPTY));
      }}
    >
      <Field label="Текущий пароль" htmlFor="pw-current" error={fieldErrors.currentPassword}>
        <Input id="pw-current" name="currentPassword" type="password" autoComplete="current-password" required value={values.currentPassword} onChange={(e) => set("currentPassword", e.target.value)} />
      </Field>
      <Field label="Новый пароль" htmlFor="pw-new" error={fieldErrors.newPassword} hint="Не короче 10 символов, не совпадает с email и текущим паролем">
        <Input id="pw-new" name="newPassword" type="password" autoComplete="new-password" required minLength={10} value={values.newPassword} onChange={(e) => set("newPassword", e.target.value)} />
      </Field>
      <Field label="Повторите новый пароль" htmlFor="pw-confirm" error={fieldErrors.confirmPassword}>
        <Input id="pw-confirm" name="confirmPassword" type="password" autoComplete="new-password" required value={values.confirmPassword} onChange={(e) => set("confirmPassword", e.target.value)} />
      </Field>
      <Button type="submit" loading={isPending}>
        <KeyRound /> Сменить пароль
      </Button>
    </form>
  );
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { ShieldCheck, UserRound } from "lucide-react";
import { Card, CardContent, CardHeader, DataList, PageHeader } from "@/components/ui/primitives";
import { ChangePasswordForm } from "@/components/admin/change-password-form";
import { requireSession } from "@/lib/auth/dal";
import { ROLE_LABELS } from "@/lib/auth/permissions";
import { prisma } from "@/lib/prisma";
import { formatDateTime } from "@/lib/format";

export const metadata: Metadata = { title: "Профиль" };

export default async function ProfilePage() {
  const session = await requireSession();
  const user = await prisma.user.findUnique({
    where: { id: session.userId },
    select: { email: true, name: true, role: true, passwordChangedAt: true },
  });
  if (!user) notFound();
  return (
    <>
      <PageHeader title="Профиль" description="Учётная запись и безопасность входа" />
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-2 lg:gap-6">
        <Card>
          <CardHeader icon={<UserRound />} title="Учётная запись" />
          <CardContent>
            <DataList
              items={[
                { label: "Имя", value: user.name },
                { label: "Email", value: user.email, mono: true },
                { label: "Роль", value: ROLE_LABELS[user.role] ?? user.role },
                { label: "Пароль изменён", value: user.passwordChangedAt ? formatDateTime(user.passwordChangedAt) : "ещё не менялся" },
              ]}
            />
          </CardContent>
        </Card>
        <Card>
          <CardHeader icon={<ShieldCheck />} title="Смена пароля" description="После смены сеансы на других устройствах завершатся" />
          <CardContent>
            <ChangePasswordForm />
          </CardContent>
        </Card>
      </div>
    </>
  );
}

"use client";

import { useState } from "react";
import { UserPlus } from "lucide-react";
import { changeUserRoleAction, createUserAction } from "@/actions/admin";
import { Button } from "@/components/ui/button";
import { Field, Input, Select } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { useServerAction } from "@/components/use-server-action";
import { ROLES, ROLE_LABELS, type Role } from "@/lib/auth/permissions";

export function RoleSelect({ userId, role, disabled, label }: { userId: string; role: string; disabled: boolean; label: string }) {
  const [value, setValue] = useState(role);
  const { run, isPending } = useServerAction();
  return (
    <div className="flex items-center gap-2">
      <Select id={`role-${userId}`} name="role" aria-label={label} value={value} disabled={disabled || isPending} onChange={(e) => setValue(e.target.value)} className="min-w-44">
        {ROLES.map((r) => (
          <option key={r} value={r}>
            {ROLE_LABELS[r]}
          </option>
        ))}
      </Select>
      {value !== role && (
        <Button size="sm" loading={isPending} onClick={() => run(() => changeUserRoleAction(userId, { role: value as Role }))}>
          Сохранить
        </Button>
      )}
    </div>
  );
}

const EMPTY_USER = { email: "", name: "", role: "INSPECTOR", password: "" };

export function NewUserButton() {
  const [open, setOpen] = useState(false);
  const [values, setValues] = useState(EMPTY_USER);
  const { run, isPending, fieldErrors } = useServerAction();
  const set = (key: keyof typeof values, value: string) => setValues((prev) => ({ ...prev, [key]: value }));
  return (
    <>
      <Button onClick={() => setOpen(true)}>
        <UserPlus /> Новый пользователь
      </Button>
      <Sheet open={open} onClose={() => setOpen(false)} title="Новый пользователь" description="Временный пароль передайте лично — пользователь сменит его в профиле">
        <form
          className="space-y-4"
          onSubmit={(e) => {
            e.preventDefault();
            run(
              () => createUserAction({ ...values, role: values.role as Role }),
              () => {
                setOpen(false);
                setValues(EMPTY_USER);
              },
            );
          }}
        >
          <Field label="Email" htmlFor="nu-email" error={fieldErrors.email}>
            <Input id="nu-email" name="email" type="email" autoComplete="off" required value={values.email} onChange={(e) => set("email", e.target.value)} />
          </Field>
          <Field label="Имя" htmlFor="nu-name" error={fieldErrors.name}>
            <Input id="nu-name" name="name" required value={values.name} onChange={(e) => set("name", e.target.value)} />
          </Field>
          <Field label="Роль" htmlFor="nu-role" error={fieldErrors.role}>
            <Select id="nu-role" name="role" value={values.role} onChange={(e) => set("role", e.target.value)}>
              {ROLES.map((r) => (
                <option key={r} value={r}>
                  {ROLE_LABELS[r]}
                </option>
              ))}
            </Select>
          </Field>
          <Field label="Временный пароль" htmlFor="nu-password" error={fieldErrors.password} hint="Не короче 10 символов">
            <Input id="nu-password" name="password" type="password" autoComplete="new-password" required minLength={10} value={values.password} onChange={(e) => set("password", e.target.value)} />
          </Field>
          <Button type="submit" size="lg" className="w-full" loading={isPending}>
            <UserPlus /> Создать
          </Button>
        </form>
      </Sheet>
    </>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { History, Users } from "lucide-react";
import { Badge, Card, CardHeader, EmptyState, PageHeader } from "@/components/ui/primitives";
import { NewUserButton, RoleSelect } from "@/components/admin/user-admin";
import { requireSession } from "@/lib/auth/dal";
import { can } from "@/lib/auth/permissions";
import { AUDIT_ACTION_LABELS, type AuditAction } from "@/lib/audit";
import { prisma } from "@/lib/prisma";
import { formatDateTime } from "@/lib/format";
import { cn } from "@/lib/utils";

export const metadata: Metadata = { title: "Администрирование" };

const AUDIT_PAGE_SIZE = 100;
const CHIP = "inline-flex min-h-11 items-center rounded-full px-3 text-xs font-medium sm:min-h-8";

export default async function AdminPage({ searchParams }: { searchParams: Promise<{ action?: string }> }) {
  const session = await requireSession();
  if (!can(session.role, "users:manage")) notFound();
  const { action } = await searchParams;
  const filter = action && action in AUDIT_ACTION_LABELS ? (action as AuditAction) : undefined;

  const [users, logs] = await Promise.all([
    prisma.user.findMany({ orderBy: [{ role: "asc" }, { email: "asc" }], select: { id: true, email: true, name: true, role: true } }),
    prisma.auditLog.findMany({ where: filter ? { action: filter } : undefined, orderBy: { createdAt: "desc" }, take: AUDIT_PAGE_SIZE }),
  ]);

  return (
    <>
      <PageHeader title="Администрирование" description="Пользователи, роли и аудит-журнал операций" actions={<NewUserButton />} />

      <Card className="mb-4 lg:mb-6">
        <CardHeader icon={<Users />} title="Пользователи" description="Смена роли завершает все сеансы пользователя" />
        <ul className="divide-y divide-slate-100">
          {users.map((u) => (
            <li key={u.id} className="flex flex-col gap-2 px-5 py-3 sm:flex-row sm:items-center sm:justify-between">
              <div className="min-w-0">
                <p className="font-medium text-slate-900">
                  {u.name} {u.id === session.userId && <Badge tone="indigo">это вы</Badge>}
                </p>
                <p className="font-mono text-xs text-slate-500">{u.email}</p>
              </div>
              <RoleSelect userId={u.id} role={u.role} disabled={u.id === session.userId} label={`Роль пользователя ${u.email}`} />
            </li>
          ))}
        </ul>
      </Card>

      <Card>
        <CardHeader icon={<History />} title="Аудит-журнал" description={`Последние ${AUDIT_PAGE_SIZE} операций: кто, когда, что`} />
        <nav aria-label="Фильтр аудит-журнала" className="flex flex-wrap gap-1.5 border-b border-slate-100 px-5 pb-3">
          <Link href="/admin" aria-current={!filter ? "page" : undefined} className={cn(CHIP, !filter ? "bg-slate-900 text-white" : "bg-slate-100 text-slate-600")}>
            Все
          </Link>
          {(Object.keys(AUDIT_ACTION_LABELS) as AuditAction[]).map((a) => (
            <Link key={a} href={`/admin?action=${a}`} aria-current={filter === a ? "page" : undefined} className={cn(CHIP, filter === a ? "bg-slate-900 text-white" : "bg-slate-100 text-slate-600")}>
              {AUDIT_ACTION_LABELS[a]}
            </Link>
          ))}
        </nav>
        {logs.length === 0 ? (
          <EmptyState icon={<History />} title="Записей нет" description="Операции появятся здесь сразу после выполнения" />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <caption className="sr-only">Аудит-журнал операций</caption>
              <thead className="bg-slate-50 text-left text-xs text-slate-500">
                <tr>
                  <th scope="col" className="px-5 py-2 font-medium">Когда</th>
                  <th scope="col" className="px-3 py-2 font-medium">Кто</th>
                  <th scope="col" className="px-3 py-2 font-medium">Операция</th>
                  <th scope="col" className="px-3 py-2 font-medium">Что</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map((log) => (
                  <tr key={log.id}>
                    <td className="px-5 py-2 font-mono text-xs whitespace-nowrap text-slate-500">{formatDateTime(log.createdAt)}</td>
                    <td className="px-3 py-2 text-xs whitespace-nowrap">{log.actorName}</td>
                    <td className="px-3 py-2 text-xs whitespace-nowrap">{AUDIT_ACTION_LABELS[log.action as AuditAction] ?? log.action}</td>
                    <td className="px-3 py-2 text-xs text-slate-700">{log.summary}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </>
  );
}

