-- 4.4: поиск по подстроке номера на сервере. GIN-индекс pg_trgm ускоряет LIKE '%%2918%%' при тысячах единиц.
-- Расширение pg_trgm есть в PostgreSQL contrib (Neon, Supabase, RDS) — создаётся владельцем базы.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX IF NOT EXISTS "Container_bicCode_trgm_idx" ON "Container" USING GIN ("bicCode" gin_trgm_ops);
/**
 * CSV для русскоязычного Excel: UTF-8 с BOM (иначе кириллица превращается в «кракозябры»),
 * разделитель «;» (запятая — десятичный разделитель в ru-RU), переводы строк CRLF.
 */
import { formatDate } from "./format";

export const CSV_BOM = String.fromCharCode(0xfeff); // UTF-8 BOM, U+FEFF
const DELIMITER = ";";
const LINE_BREAK = "\r\n";
/** Символы, с которых Excel начинает формулу — защита от CSV/формула-инъекций. */
const FORMULA_PREFIX = /^[=+\-@\t\r\n＝＋－＠]/;
const NEEDS_QUOTES = /[";\r\n]/;
/** Телефон вида «+7 812 336-50-20»: только безопасные символы — можно отдать как текстовую константу Excel. */
const PHONE_LIKE = /^\+[\d\s()-]+$/;

export type CsvCell = string | number | boolean | Date | null | undefined;

export interface CsvColumn<T> {
  header: string;
  value: (row: T) => CsvCell;
}

function formatNumber(value: number): string {
  if (!Number.isFinite(value)) return "";
  const text = Number.isInteger(value) ? String(value) : value.toFixed(2);
  return text.replace(".", ",");
}

function quote(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

function escapeText(value: string): string {
  // ="+7 …" Excel показывает как обычный текст, без апострофа; шаблон PHONE_LIKE исключает инъекцию.
  if (PHONE_LIKE.test(value)) return quote(`="${value}"`);
  const safe = FORMULA_PREFIX.test(value) ? `'${value}` : value;
  return NEEDS_QUOTES.test(safe) ? quote(safe) : safe;
}

export function formatCsvCell(value: CsvCell): string {
"use client";

import { FileSpreadsheet } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { buildCsv, csvFilename, downloadCsv, type CsvColumn } from "@/lib/csv";
import { cn } from "@/lib/utils";

interface ExportCsvButtonProps<T> {
  rows: readonly T[];
  columns: readonly CsvColumn<T>[];
  /** Префикс имени файла, например «fms-registry». */
  filePrefix: string;
  className?: string;
}

/** Выгрузка текущей (отфильтрованной) выборки в CSV для Excel. */
export function ExportCsvButton<T>({ rows, columns, filePrefix, className }: ExportCsvButtonProps<T>) {
  function handleExport() {
    if (rows.length === 0) {
      toast.info("Нет строк для выгрузки — измените фильтры");
      return;
    }
    downloadCsv(csvFilename(filePrefix), buildCsv(rows, columns));
    toast.success(`Выгружено строк: ${rows.length}`);
  }

  return (
    <Button variant="outline" className={cn("h-11 lg:h-10", className)} onClick={handleExport} title="Скачать текущую выборку в CSV (Excel)" aria-label="Выгрузить в Excel (CSV)">
      <FileSpreadsheet className="text-emerald-600" />
      <span className="hidden sm:inline">Excel / CSV</span>
    </Button>
  );
}

