      currentLocode: c.currentLocode,
      currentTerminal: c.currentTerminal,
      cscPlateExpiry: c.cscPlateExpiry,
      csc: flags.csc,
      idleDays: flags.storage.idleDays,
      isIdleTooLong: flags.storage.isIdleTooLong,
