      totalRevenueUsd: c.totalRevenueUsd,
      needsAttention: flags.any,
      needsRepair: flags.needsRepair,
      activity,
      activityHref,
      tripTiming: trip ? computeTripTiming(trip, now) : null,
      recentEvents: c.events,
    };
  });

