const lib = require("C:/projects/Тест для АБ/node_modules/@vitest/istanbul-lib-coverage");
const map = lib.createCoverageMap({});
for (const f of [
  "C:/Users/Eugen/AppData/Local/Temp/fmstools/cov-unit2/coverage-final.json",
  "C:/Users/Eugen/AppData/Local/Temp/fmstools/cov-int/coverage-final.json",
]) map.merge(require(f));
const rows = [];
const total = lib.createCoverageSummary();
for (const file of map.files()) {
  const s = map.fileCoverageFor(file).toSummary();
  total.merge(s);
  const name = "src/" + file.split(/[\\/]src[\\/]/).pop().split("\\").join("/");
  rows.push([name, s.lines.pct, s.branches.pct, s.functions.pct]);
